var QNA=[{"id": "2211-30", "short": "22년 11월 30번", "group": "22년 11월", "num": 30, "topic_ko": "카운터셰이딩이 동물을 배경과 섞이게 하는 원리", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 1, "summary_ko": "카운터셰이딩은 동물에게 위장을 제공하는 시각적 평평화 과정"}, {"n": 2, "label": "원리", "from": 2, "to": 5, "summary_ko": "빛을 받은 물체는 아래로 갈수록 어두워져 모양이 드러나므로, 균일한 색의 동물은 눈에 띔"}, {"n": 3, "label": "결과", "from": 6, "to": 10, "summary_ko": "대부분 동물은 윗부분이 더 어두워 빛을 받으면 한 색처럼 보여 배경과 섞임"}], "gloss": [{"w": "countershading", "m": "카운터셰이딩(명암역위형 보호색)"}, {"w": "camouflage", "m": "위장"}, {"w": "illuminate", "m": "(빛을) 비추다", "form": "illuminated", "note": "동사 illuminate의 과거분사형, 'be illuminated'는 '빛을 받다'"}, {"w": "gradually", "m": "점차"}, {"w": "shade", "m": "음영이 생기다, 그늘지게 하다", "form": "shaded", "note": "동사 shade의 과거분사형, 수동 의미('음영이 생기다')"}, {"w": "distinguish", "m": "식별하다, 구별하다"}, {"w": "uniformly", "m": "균일하게"}, {"w": "substrate", "m": "밑바탕, 바탕면(동물이 놓인 표면)"}, {"w": "belly", "m": "복부, 배"}, {"w": "blend in", "m": "섞이다, 어우러지다", "form": "blends in", "note": "동사구 blend in의 3인칭 단수형(주어 The animal이 단수)"}, {"w": "coloration", "m": "배색, 색깔 배치"}, {"w": "visible", "m": "눈에 보이는, 눈에 띄는"}], "qa": [{"chunk": 1, "q": "첫 문장에서 설명하는 카운터셰이딩은 무엇인가?", "opts": ["동물이 빛을 흡수해 체온을 높이는 과정", "동물의 모양을 더 뚜렷하게 보이게 하는 과정", "동물에게 위장을 제공하는, 시각적으로 평평하게 만드는 과정"], "ans": 2, "why": ["첫 문장이 곧 정의임.", "카운터셰이딩은 시각적으로 평평하게 만들어 동물에게 위장을 제공하는 과정임.", "체온을 높이는 과정이라는 말은 지문에 없음.", "모양을 뚜렷하게 하는 것이 아니라 오히려 모양의 인상을 없애 줌."], "ev_en": "Countershading is the process of optical flattening that provides camouflage to animals.", "ev_ko": "카운터셰이딩(명암역위형보호색)은 동물에게 위장을 제공하는 시각적으로 평평하게 하는 과정이다."}, {"chunk": 2, "q": "동물이 밑바탕과 정확히 같지만 균일한 색이라면, 빛을 받을 때 어떻게 되는가?", "opts": ["쉽게 눈에 띈다.", "배경과 섞여 보이지 않게 된다.", "몸 윗부분이 아랫부분보다 어둡게 보인다."], "ans": 0, "why": ["위에서 빛을 받으면 물체는 위가 가장 밝고 아래로 갈수록 어두워짐.", "이 음영 때문에 보는 사람이 모양을 알아봄.", "그래서 색이 균일해도 빛을 받으면 쉽게 눈에 띔.", "'윗부분이 더 어둡게 보인다'는 지문과 다름. 색이 균일한 동물은 위에서 빛을 받으면 맨 위가 가장 밝음(brightest on top, 맨 위에서 가장 밝은).", "윗부분이 더 어두운 동물은 다음 덩어리(6번 문장 이후)의 경우이고, 그런 동물이 배경과 섞임."], "ev_en": "Thus even if an animal is exactly, but uniformly, the same color as the substrate, it will be easily visible when illuminated.", "ev_ko": "따라서 비록 동물이 밑바탕과 정확하지만 균일하게 같은 색일지라도 빛이 비춰질 때 쉽게 눈에 띌 것이다."}, {"chunk": 3, "q": "대부분의 동물이 위에서 빛을 받으면 어떻게 보이는가?", "opts": ["등과 복부가 뚜렷하게 나뉘어 보인다.", "등이 더 어두워져 눈에 잘 띈다.", "하나의 색처럼 보여 밑바탕과 쉽게 섞인다."], "ans": 2, "why": ["대부분의 동물은 아랫부분보다 윗부분이 더 어두움.", "빛을 받으면 어두운 등은 밝아지고 밝은 복부는 음영이 생김.", "결과적으로 하나의 색처럼 보여 배경과 섞임.", "등이 더 어두워지는 것이 아니라 오히려 밝아지고, 등과 복부가 뚜렷이 나뉘어 보이는 것이 아니라 하나의 색처럼 보임."], "ev_en": "The animal thus appears to be a single color and easily blends in with the substrate.", "ev_ko": "따라서 동물은 하나의 색처럼 보이고 밑바탕과 쉽게 섞인다."}], "tf": [{"s": "물체가 위에서 빛을 받으면 맨 위가 가장 밝게 보인다.", "t": true, "why": ["위에서 빛이 비치면 윗부분이 가장 밝음.", "지문 내용과 일치함."], "ev_en": "When sunlight illuminates an object from above, the object will be brightest on top.", "ev_ko": "햇빛이 물체를 위에서 비출 때, 그 물체는 맨 위에서 가장 밝을 것이다."}, {"s": "빛을 받은 물체의 색은 아래로 갈수록 점차 더 밝게 변한다.", "t": false, "why": ["아래로 갈수록 더 어두워지므로 틀림.", "올바른 내용은 '아래로 갈수록 점차 더 어두운색으로 음영이 생긴다'임."], "ev_en": "The color of the object will gradually shade darker toward the bottom.", "ev_ko": "물체의 색깔은 맨 아래로 향할수록 점차 더 어두운색으로 음영이 생기게 될 것이다."}, {"s": "대부분의 동물은 아랫부분보다 윗부분이 더 어둡다.", "t": true, "why": ["대부분의 동물은 등이 어둡고 배가 밝음.", "지문 내용과 일치함."], "ev_en": "Most animals, however, are darker above than they are below.", "ev_ko": "그러나 대부분의 동물은 아랫부분보다 윗부분이 더 어둡다."}, {"s": "위에서 빛을 받으면 동물의 어두운 등은 더 어두워지고 밝은 복부는 더 밝아진다.", "t": false, "why": ["방향이 반대임.", "올바른 내용은 어두운 등은 밝아지고 밝은 복부는 음영이 생긴다는 것임."], "ev_en": "When they are illuminated from above, the darker back is lightened and the lighter belly is shaded.", "ev_ko": "그들이 위에서 빛을 받을 때, 더 어두운 등은 밝아지고 더 밝은 복부는 음영이 생긴다."}, {"s": "카운터셰이딩은 생물체의 모양에 대한 시각적 인상을 없애 준다.", "t": true, "why": ["카운터셰이딩은 모양의 시각적 인상을 파괴함.", "그 결과 동물이 배경과 섞임."], "ev_en": "This pattern of coloration, or countershading, destroys the visual impression of shape in the organism.", "ev_ko": "이러한 형태의 배색 즉, 카운터셰이딩은 생물체의 모양의 시각적 인상을 파괴한다."}], "flow": {"fixed": "카운터셰이딩은 동물에게 위장을 제공하는, 시각적으로 평평하게 만드는 과정이다.", "order": ["물체는 위에서 빛을 받으면 맨 위가 가장 밝고 아래로 갈수록 점차 어두워지는데, 이 음영 덕분에 보는 사람은 그 모양을 알아볼 수 있다.", "그래서 동물이 밑바탕과 똑같은 색이라도 색이 균일하기만 하면, 이런 음영 때문에 모양이 드러나 빛을 받을 때 쉽게 눈에 띈다.", "하지만 대부분의 동물은 그렇게 균일한 색이 아니라 윗부분이 더 어두워서, 빛을 받으면 하나의 색처럼 보이고 그 결과 배경과 쉽게 섞인다."], "clue": ["첫 덩어리가 말한 과정의 원리(빛과 음영)를 풀어 주는 설명이 이어짐", "'이런 음영'이 앞 덩어리의 음영 설명을 가리키고 '그래서'로 균일한 색 동물이 눈에 띄는 결과를 이끎", "'그렇게 균일한 색이 아니라'가 앞 덩어리의 균일한 색 동물과 대비되고 '하지만'으로 반대 경우를 제시함"], "why": ["정의, 원리, 눈에 띄는 경우, 반대로 섞이는 경우 순으로 흐름."], "cards": ["하지만 대부분의 동물은 그렇게 균일한 색이 아니라 윗부분이 더 어두워서, 빛을 받으면 하나의 색처럼 보이고 그 결과 배경과 쉽게 섞인다.", "그래서 동물이 밑바탕과 똑같은 색이라도 색이 균일하기만 하면, 이런 음영 때문에 모양이 드러나 빛을 받을 때 쉽게 눈에 띈다.", "물체는 위에서 빛을 받으면 맨 위가 가장 밝고 아래로 갈수록 점차 어두워지는데, 이 음영 덕분에 보는 사람은 그 모양을 알아볼 수 있다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Countershading is the process of optical flattening that provides camouflage to animals.", "ko": "카운터셰이딩(명암역위형보호색)은 동물에게 위장을 제공하는 시각적으로 평평하게 하는 과정이다."}, {"n": 2, "en": "When sunlight illuminates an object from above, the object will be brightest on top.", "ko": "햇빛이 물체를 위에서 비출 때, 그 물체는 맨 위에서 가장 밝을 것이다."}, {"n": 3, "en": "The color of the object will gradually shade darker toward the bottom.", "ko": "물체의 색깔은 맨 아래로 향할수록 점차 더 어두운색으로 음영이 생기게 될 것이다."}, {"n": 4, "en": "This shading gives the object depth and allows the viewer to distinguish its shape.", "ko": "이러한 음영은 물체에 농도를 주고 보는 사람이 그것의 모양을 식별하게 해 준다."}, {"n": 5, "en": "Thus even if an animal is exactly, but uniformly, the same color as the substrate, it will be easily visible when illuminated.", "ko": "따라서 비록 동물이 밑바탕과 정확하지만 균일하게 같은 색일지라도 빛이 비춰질 때 쉽게 눈에 띌 것이다."}, {"n": 6, "en": "Most animals, however, are darker above than they are below.", "ko": "그러나 대부분의 동물은 아랫부분보다 윗부분이 더 어둡다."}, {"n": 7, "en": "When they are illuminated from above, the darker back is lightened and the lighter belly is shaded.", "ko": "그들이 위에서 빛을 받을 때, 더 어두운 등은 밝아지고 더 밝은 복부는 음영이 생긴다."}, {"n": 8, "en": "The animal thus appears to be a single color and easily blends in with the substrate.", "ko": "따라서 동물은 하나의 색처럼 보이고 밑바탕과 쉽게 섞인다."}, {"n": 9, "en": "This pattern of coloration, or countershading, destroys the visual impression of shape in the organism.", "ko": "이러한 형태의 배색 즉, 카운터셰이딩은 생물체의 모양의 시각적 인상을 파괴한다."}, {"n": 10, "en": "It allows the animal to blend in with its background.", "ko": "그것은 동물이 그것의 배경과 섞이게 해 준다."}]}, {"id": "2211-33", "short": "22년 11월 33번", "group": "22년 11월", "num": 33, "topic_ko": "음수가 불쾌해서 기호를 피하려는 사람들의 전략", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 1, "summary_ko": "음수는 양수보다 추상적이지만 일상에서 생각해야 함"}, {"n": 2, "label": "중심 내용", "from": 2, "to": 3, "summary_ko": "많은 사람이 음수와 잘 지내지 못해 음수 기호를 피하는 전략을 만들어 냄"}, {"n": 3, "label": "뒷받침", "from": 4, "to": 8, "summary_ko": "펀드 손실, 역사, 지하층, 기온 표현 등에서 음수 기호를 피하며 기호는 불쾌해 보임"}], "gloss": [{"w": "negative number", "m": "음수", "form": "negative numbers", "note": "명사 number의 복수형"}, {"w": "abstract", "m": "추상적인"}, {"w": "debt", "m": "빚, 채무", "form": "debts", "note": "명사 debt의 복수형"}, {"w": "contend with", "m": "~와 씨름하다, 맞서다", "form": "contending with", "note": "동사 contend의 동명사형(전치사 to 뒤)"}, {"w": "freezing", "m": "몹시 차가운"}, {"w": "make peace with", "m": "~와 화해하다, ~을 받아들이다(여기서는 음수와 잘 지내다)", "form": "made peace with", "note": "동사 make의 과거분사형(haven't made = 현재완료 부정)"}, {"w": "invent", "m": "만들어 내다, 고안하다", "form": "invented", "note": "동사 invent의 과거분사형(have invented = 현재완료)"}, {"w": "sidestep", "m": "피하다"}, {"w": "dread", "m": "두려워하다", "form": "dreaded", "note": "동사 dread의 과거분사형이 형용사처럼 쓰여 '두려운'이라는 뜻이 됨"}, {"w": "loss", "m": "손실", "form": "losses", "note": "명사 loss의 복수형"}, {"w": "parenthesis", "m": "괄호", "form": "parentheses", "note": "명사 parenthesis의 복수형(-is가 -es로 바뀜)"}, {"w": "designation", "m": "명칭, 표시", "form": "designations", "note": "명사 designation의 복수형"}, {"w": "exception", "m": "예외", "form": "exceptions", "note": "명사 exception의 복수형"}, {"w": "unpleasant", "m": "불쾌한"}], "qa": [{"chunk": 1, "q": "첫 문장의 핵심 내용으로 알맞은 것은?", "opts": ["음수는 양수보다 구체적이어서 일상에서 쉽게 쓰인다.", "음수는 일상에서 거의 쓰이지 않아 몰라도 된다.", "음수는 양수보다 추상적이지만 일상생활 모든 면에서 생각해야 한다."], "ans": 2, "why": ["1번 문장이 근거이다.", "음수는 양수보다 훨씬 더 추상적이다(a lot more abstract)라고 한다.", "그래도 일상생활의 모든 측면에서(in all aspects of daily life) 음수를 생각해야 한다고 한다.", "\u201c음수가 구체적이어서 쉽게 쓰인다\u201d는 진술은 지문과 반대이다.", "\u201c음수는 거의 쓰이지 않아 몰라도 된다\u201d는 진술도 일상에서 생각해야 한다는 말과 어긋난다."], "ev_en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ev_ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"chunk": 2, "q": "음수와 잘 지내지 못하는 사람들이 한 일은?", "opts": ["음수를 아예 배우지 않으려 했다.", "음수 기호를 피하기 위한 여러 정신적 전략을 만들어 냈다.", "음수를 양수로 바꾸는 법을 만들어 냈다."], "ans": 1, "why": ["3번 문장이 근거이다.", "사람들은 두려운 음수 기호를 피하려는(to sidestep the dreaded negative sign) 전략을 만들어 냈다.", "funny little mental strategies(우스꽝스럽고 사소한 정신적 전략)라고 표현한다.", "\u201c음수를 아예 배우지 않으려 했다\u201d는 진술은 지문에 없다.", "\u201c음수를 양수로 바꾸는 법을 만들어 냈다\u201d는 진술도 지문에 없다. 피하는 대상은 음수 자체가 아니라 음수 기호이다."], "ev_en": "People have invented all sorts of funny little mental strategies to sidestep the dreaded negative sign.", "ev_ko": "사람들은 그 두려운 음수의 기호를 피하기 위해 모든 종류의 우스꽝스럽고 사소한 정신적 전략들을 만들어 냈다."}, {"chunk": 3, "q": "뒷받침 예시들이 공통으로 보여 주는 것은?", "opts": ["음수는 금융 분야에서만 쓰인다.", "사람들은 음수 기호를 쓰는 것을 피하려고 한다.", "음수 기호를 쓰면 계산이 훨씬 쉬워진다."], "ans": 1, "why": ["펀드 손실은 빨간색이나 괄호로 표시해 음수 기호를 쓰지 않음.", "역사책의 기원전 100년(100 B.C.), 주차장의 B1\u00b7B2(지하 1층\u00b7지하 2층 표시)도 음수 기호를 피한 표현임.", "기온은 -5도라고 말하는 사람도 있지만 5 below zero(영하 5도)를 선호하는 사람이 많음.", "8번 문장은 앞의 예시들을 묶어 음수 기호 자체가 불쾌하다는 공통 이유를 말해 주는 근거임.", "\u201c금융 분야에서만 쓰인다\u201d는 진술은 역사\u00b7주차장\u00b7기온 예시와 맞지 않고 지문에도 없음.", "\u201c계산이 훨씬 쉬워진다\u201d는 진술도 지문에 없음."], "ev_en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ev_ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}], "tf": [{"s": "\u2018-4개의 쿠키\u2019처럼 음수로 된 양은 눈으로 볼 수 없다.", "t": true, "why": ["1번 문장이 근거이다.", "you can\u2019t see negative 4 cookies(음수 4개의 쿠키를 볼 수 없다)고 한다.", "음수가 양수보다 훨씬 더 추상적인 예로 든 말이다.", "지문 내용과 일치함."], "ev_en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ev_ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"s": "많은 사람은 이제 음수와 완전히 잘 지내게 되었다.", "t": false, "why": ["2번 문장은 many of us haven\u2019t quite made peace with negative numbers(우리 중 많은 사람은 음수와 아직 완전히 잘 지내지는 못했다)라고 한다.", "올바른 내용은 음수를 아직 받아들이지 못한 사람이 많다는 것임."], "ev_en": "Still, many of us haven\u2019t quite made peace with negative numbers.", "ev_ko": "여전히 우리들 중 많은 사람들은 음수와 잘 지내지 못해 왔다."}, {"s": "뮤추얼 펀드 진술에서 손실은 음수 기호를 붙여 표시한다.", "t": false, "why": ["4번 문장은 손실이 빨간색으로 인쇄되거나 괄호 안에 들어간다고 한다.", "with no negative sign to be found(음수 기호가 발견되지 않음)가 핵심이므로 틀림.", "올바른 내용은 음수 기호 없이 빨간색이나 괄호로 표시한다는 것임."], "ev_en": "On mutual fund statements, losses (negative numbers) are printed in red or stuck in parentheses with no negative sign to be found.", "ev_ko": "뮤추얼 펀드(계약형 투자 신탁) 진술에서 손실(음수)은 빨간색으로 인쇄되거나 음수의 기호가 발견되지 않은 채 괄호 안에 갇혀 있다."}, {"s": "역사책은 Julius Caesar가 \u2013100년에 태어났다고 말한다.", "t": false, "why": ["5번 문장은 born in 100 B.C., not \u2013100(\u2013100이 아닌 기원전 100년에 태어났다)이라고 한다.", "올바른 내용은 음수 표기 대신 기원전 100년이라고 쓴다는 것임."], "ev_en": "The history books tell us that Julius Caesar was born in 100 B.C., not \u2011100.", "ev_ko": "역사책은 우리에게 Julius Caesar가 \u2013100이 아닌 기원전 100년에 태어났다고 말한다."}, {"s": "음수 기호에는 정말 불쾌하게 보이는 무언가가 있다고 한다.", "t": true, "why": ["8번 문장이 근거이다.", "that negative sign that just looks so unpleasant(정말 불쾌하게만 보이는 그 음수 기호)라고 한다.", "사람들이 음수 기호를 피하려는 이유를 정리한 문장임.", "지문 내용과 일치함."], "ev_en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ev_ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}], "flow": {"fixed": "음수는 양수보다 훨씬 추상적이지만, 우리는 일상생활의 모든 면에서 음수를 생각해야 한다.", "order": ["그런데도 우리 중 많은 사람은 여전히 음수와 잘 지내지 못한다.", "그래서 사람들은 그 두려운 음수 기호를 피하려고 온갖 우스꽝스럽고 사소한 정신적 전략을 만들어 냈다.", "예를 들어 펀드 손실은 빨간색이나 괄호로, 역사는 기원전 100년으로 표현하고, 기온도 -5도라고 말하는 사람이 있기는 하지만 많은 사람이 영하 5도라고 말하길 선호하는데, 음수 기호가 그만큼 불쾌해 보이기 때문이다."], "clue": ["'그런데도'는 필요하다는 앞 내용과 대비되는 현실을 이끎", "'그래서'는 잘 지내지 못하는 상황의 결과를 이끎", "'예를 들어'는 앞의 전략들을 구체적으로 보여 줌"], "why": ["필요하지만 불편하다, 그래서 피하는 전략이 생겼다, 예시 순으로 흐름."], "cards": ["예를 들어 펀드 손실은 빨간색이나 괄호로, 역사는 기원전 100년으로 표현하고, 기온도 -5도라고 말하는 사람이 있기는 하지만 많은 사람이 영하 5도라고 말하길 선호하는데, 음수 기호가 그만큼 불쾌해 보이기 때문이다.", "그래서 사람들은 그 두려운 음수 기호를 피하려고 온갖 우스꽝스럽고 사소한 정신적 전략을 만들어 냈다.", "그런데도 우리 중 많은 사람은 여전히 음수와 잘 지내지 못한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"n": 2, "en": "Still, many of us haven\u2019t quite made peace with negative numbers.", "ko": "여전히 우리들 중 많은 사람들은 음수와 잘 지내지 못해 왔다."}, {"n": 3, "en": "People have invented all sorts of funny little mental strategies to sidestep the dreaded negative sign.", "ko": "사람들은 그 두려운 음수의 기호를 피하기 위해 모든 종류의 우스꽝스럽고 사소한 정신적 전략들을 만들어 냈다."}, {"n": 4, "en": "On mutual fund statements, losses (negative numbers) are printed in red or stuck in parentheses with no negative sign to be found.", "ko": "뮤추얼 펀드(계약형 투자 신탁) 진술에서 손실(음수)은 빨간색으로 인쇄되거나 음수의 기호가 발견되지 않은 채 괄호 안에 갇혀 있다."}, {"n": 5, "en": "The history books tell us that Julius Caesar was born in 100 B.C., not \u2011100.", "ko": "역사책은 우리에게 Julius Caesar가 \u2013100이 아닌 기원전 100년에 태어났다고 말한다."}, {"n": 6, "en": "The underground levels in a parking garage often have designations like B1 and B2.", "ko": "주차장의 지하층은 종종 B1과 B2와 같은 명칭을 가지고 있다."}, {"n": 7, "en": "Temperatures are one of the few exceptions: folks do say, especially here in Ithaca, New York, that it\u2019s \u20115 degrees outside, though even then, many prefer to say 5 below zero.", "ko": "기온은 몇 안 되는 예외 중 하나인데 특히 여기 New York의 Ithaca에서 사람들은 바깥의 기온이 \u20135도라고 말하지만 심지어 그때에도 많은 사람들은 영하 5도라고 말하길 선호한다."}, {"n": 8, "en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}]}, {"id": "2211-34", "short": "22년 11월 34번", "group": "22년 11월", "num": 34, "topic_ko": "교란 변수가 인간 관찰 연구의 인과적 결론을 해침", "chunks": [{"n": 1, "label": "중심 내용", "from": 1, "to": 4, "summary_ko": "인간은 동질적이지 않아 교란 변수가 인과적 결론 도출 능력을 손상시킴"}, {"n": 2, "label": "뒷받침\u2460", "from": 5, "to": 8, "summary_ko": "교란 변수는 특정 변수의 영향을 분리하기 어렵게 하며 흡연이 예시"}, {"n": 3, "label": "뒷받침\u2461", "from": 9, "to": 10, "summary_ko": "알려진 교란 변수는 수정 가능하나 알려지지 않으면 신뢰성을 손상시킴"}], "gloss": [{"w": "observational", "m": "관찰의"}, {"w": "properly", "m": "적절하게"}, {"w": "insufficiently", "m": "불충분하게"}, {"w": "homogeneous", "m": "동질적인"}, {"w": "subject", "m": "(실험) 대상", "form": "subjects", "note": "명사 subject의 복수형"}, {"w": "confounding factor", "m": "교란 변수", "form": "confounding factors", "note": "명사 factor의 복수형"}, {"w": "undermine", "m": "손상시키다, 약화시키다"}, {"w": "causal", "m": "인과적인"}, {"w": "epidemiological", "m": "역학(\u75ab\u5b78)의"}, {"w": "isolate", "m": "분리하다"}, {"w": "correlation", "m": "상관관계"}, {"w": "coronary heart disease", "m": "관상 동맥성 심장 질환"}, {"w": "correct for", "m": "~을 보정하다, 수정하다", "form": "corrected for", "note": "8번 문장에서는 동사 correct의 과거형(corrected for), 9번 문장에서는 원형 그대로 쓰임"}, {"w": "reliability", "m": "신뢰성"}], "qa": [{"chunk": 1, "q": "인간에 대한 관찰 연구가 적절히 통제될 수 없는 이유는?", "opts": ["연구에 참여하는 사람의 수가 너무 적어서", "연구자들이 인과적 결론을 내리지 않아서", "사람들이 서로 다른 생활 방식과 환경에서 살아 충분히 동질적이지 않아서"], "ans": 2, "why": ["인간은 다양한 생활 방식으로, 다양한 환경에서 삶.", "그래서 insufficiently homogeneous(충분히 동질적이지 않음)하여 실험 대상으로 적합하지 않음.", "\u201c연구에 참여하는 사람의 수가 너무 적다\u201d는 말은 지문에 없음.", "\u201c연구자들이 인과적 결론을 내리지 않는다\u201d는 말도 지문에 없음."], "ev_en": "Thus, they are insufficiently homogeneous to be suitable experimental subjects.", "ev_ko": "따라서 그들은 적절한 실험 대상이 되기에 충분히 동질적이지 않다."}, {"chunk": 2, "q": "Framingham 연구에서 커피와 심장 질환의 상관관계 대부분이 사라진 이유는?", "opts": ["커피를 마시는 많은 사람이 흡연도 한다는 점을 보정했기 때문", "커피 마시는 사람의 수가 크게 줄었기 때문", "커피가 심장 질환을 예방한다는 것이 밝혀졌기 때문"], "ans": 0, "why": ["처음에는 커피와 심장 질환 사이에 상당한 상관관계가 확인됨.", "커피 마시는 사람 중 흡연자가 많다는 사실을 보정하자 대부분 사라짐.", "여기서 흡연이 교란 변수임.", "커피 마시는 사람의 수가 줄었다는 말도, 커피가 심장 질환을 예방한다는 말도 지문에 없음."], "ev_en": "However, most of this correlation disappeared once researchers corrected for the fact that many coffee drinkers also smoke.", "ev_ko": "그러나 연구자들이 커피를 마시는 많은 사람들이 흡연도 한다는 사실에 대해 수정을 하자 이러한 상관관계의 대부분은 사라졌다."}, {"chunk": 3, "q": "교란 변수가 알려져 있지 않을 때 어떻게 되는가?", "opts": ["쉽게 수정할 수 있다.", "연구 대상이 더 동질적이 된다.", "인과적 결론의 신뢰성이 손상된다."], "ans": 2, "why": ["10번 문장이 근거이다.", "교란 변수가 알려져 있지 않으면 if they are unknown, they will undermine the reliability(신뢰성을 손상시킬 것이다)라고 한다.", "\u201c쉽게 수정할 수 있다\u201d는 보기는 9번 문장의 알려진 경우의 이야기이다.", "\u201c연구 대상이 더 동질적이 된다\u201d는 보기는 지문에 없는 내용이다."], "ev_en": "However, if they are unknown, they will undermine the reliability of the causal conclusions we draw from epidemiological surveys.", "ev_ko": "그러나 그것들이 알려져 있지 않다면, 그것들은 우리가 역학 조사로부터 도출하는 인과적 결론의 신뢰성을 손상시킬 것이다."}], "tf": [{"s": "교란 변수는 인간 역학 조사에서 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "t": true, "why": ["4번 문장이 근거이다.", "These confounding factors undermine our ability to draw sound causal conclusions(이러한 교란 변수는 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다)라고 한다.", "지문 내용과 일치함."], "ev_en": "These confounding factors undermine our ability to draw sound causal conclusions from human epidemiological surveys.", "ev_ko": "이러한 \u2018교란 변수\u2019는 인간 역학 조사로부터 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다."}, {"s": "교란 변수는 모두 연구자에게 알려져 있다.", "t": false, "why": ["5번 문장은 교란 변수를 variables (known or unknown)(알려지거나 알려지지 않은 변수)라고 정의한다.", "올바른 내용은 알려지지 않은 교란 변수도 있다는 것이다."], "ev_en": "Confounding factors are variables (known or unknown) that make it difficult for epidemiologists to isolate the effects of the specific variable being studied.", "ev_ko": "교란 변수는 역학자가 연구되고 있는 특정한 변수의 영향을 분리하기 어렵게 만드는 (알려지거나 알려지지 않은) 변수이다."}, {"s": "Taubes는 술을 마시는 사람 중에 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵다고 주장했다.", "t": true, "why": ["6번 문장이 근거이다.", "many people who drink also smoke(술을 마시는 많은 사람이 흡연도 한다)는 점이 교란 변수이다.", "그래서 알코올 섭취와 암의 연관성을 판단하기 어렵다고 Taubes는 주장했다.", "지문 내용과 일치함."], "ev_en": "For example, Taubes argued that since many people who drink also smoke, researchers have difficulty determining the link between alcohol consumption and cancer.", "ev_ko": "예를 들어, Taubes는 술을 마시는 많은 사람들이 흡연도 하기 때문에 연구자들이 알코올 섭취와 암 사이의 연관성을 결정짓는 데 어려움을 겪는다고 주장했다."}, {"s": "Framingham 연구에서는 커피와 관상 동맥성 심장 질환 사이에 상관관계가 전혀 확인되지 않았다.", "t": false, "why": ["7번 문장은 identified a significant correlation(상당한 상관관계를 확인했다)이라고 한다.", "그래서 전혀 확인되지 않았다는 말은 틀림.", "올바른 내용은 상당한 상관관계가 확인되었다가 흡연을 보정하자 대부분 사라졌다는 것임."], "ev_en": "Similarly, researchers in the famous Framingham study identified a significant correlation between coffee drinking and coronary heart disease.", "ev_ko": "마찬가지로 유명한 Framingham 연구의 연구자들은 커피를 마시는 것과 관상 동맥성 심장 질환 사이에 상당한 상관관계를 확인했다."}, {"s": "교란 변수가 알려져 있다면 그것을 수정하는 것이 종종 가능하다.", "t": true, "why": ["9번 문장이 근거이다.", "it is often possible to correct for them(그것들을 수정하는 것이 종종 가능하다)이라고 한다.", "단, 알려져 있지 않은 경우에는 신뢰성을 해친다는 10번 문장과 대비해 기억할 것."], "ev_en": "If the confounding factors are known, it is often possible to correct for them.", "ev_ko": "교란 변수들이 알려져 있다면 그것들을 수정하는 것이 종종 가능하다."}], "flow": {"fixed": "인간에 대한 관찰 연구는 적절하게 통제될 수 없는데, 사람마다 생활 방식과 환경이 달라 실험 대상으로 삼기에 충분히 동질적이지 않기 때문이다.", "order": ["사람마다 생활 방식과 환경이 다르다는 점에서 생기는 요인을 \u2018교란 변수\u2019라 하며, 이는 연구되는 변수의 영향을 분리하기 어렵게 만들어 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "이런 교란 변수의 예로, 술 마시는 사람 중에는 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵고, 커피와 심장 질환의 상관관계도 흡연을 보정하자 대부분 사라졌다.", "앞의 사례처럼 교란 변수가 알려져 있으면 종종 보정할 수 있지만, 알려져 있지 않으면 우리가 내리는 인과적 결론의 신뢰성이 손상된다."], "clue": ["\u2018교란 변수\u2019라는 용어를 처음 정의하며 소개함", "\u2018이런 교란 변수의 예로\u2019는 정의 뒤에만 올 수 있음", "\u2018앞의 사례처럼\u2019은 예시가 나온 뒤에만 올 수 있고, 알려진 경우와 알려지지 않은 경우를 대비해 마무리함"], "why": ["통제 불가 이유, 교란 변수 정의, 예시, 알려짐 여부에 따른 결과 순으로 흐름."], "cards": ["사람마다 생활 방식과 환경이 다르다는 점에서 생기는 요인을 \u2018교란 변수\u2019라 하며, 이는 연구되는 변수의 영향을 분리하기 어렵게 만들어 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "앞의 사례처럼 교란 변수가 알려져 있으면 종종 보정할 수 있지만, 알려져 있지 않으면 우리가 내리는 인과적 결론의 신뢰성이 손상된다.", "이런 교란 변수의 예로, 술 마시는 사람 중에는 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵고, 커피와 심장 질환의 상관관계도 흡연을 보정하자 대부분 사라졌다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "Observational studies of humans cannot be properly controlled.", "ko": "인간에 대한 관찰 연구는 적절하게 통제될 수 없다."}, {"n": 2, "en": "Humans live different lifestyles and in different environments.", "ko": "인간은 다양한 생활 방식으로 그리고 다양한 환경에서 살고 있다."}, {"n": 3, "en": "Thus, they are insufficiently homogeneous to be suitable experimental subjects.", "ko": "따라서 그들은 적절한 실험 대상이 되기에 충분히 동질적이지 않다."}, {"n": 4, "en": "These confounding factors undermine our ability to draw sound causal conclusions from human epidemiological surveys.", "ko": "이러한 \u2018교란 변수\u2019는 인간 역학 조사로부터 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다."}, {"n": 5, "en": "Confounding factors are variables (known or unknown) that make it difficult for epidemiologists to isolate the effects of the specific variable being studied.", "ko": "교란 변수는 역학자가 연구되고 있는 특정한 변수의 영향을 분리하기 어렵게 만드는 (알려지거나 알려지지 않은) 변수이다."}, {"n": 6, "en": "For example, Taubes argued that since many people who drink also smoke, researchers have difficulty determining the link between alcohol consumption and cancer.", "ko": "예를 들어, Taubes는 술을 마시는 많은 사람들이 흡연도 하기 때문에 연구자들이 알코올 섭취와 암 사이의 연관성을 결정짓는 데 어려움을 겪는다고 주장했다."}, {"n": 7, "en": "Similarly, researchers in the famous Framingham study identified a significant correlation between coffee drinking and coronary heart disease.", "ko": "마찬가지로 유명한 Framingham 연구의 연구자들은 커피를 마시는 것과 관상 동맥성 심장 질환 사이에 상당한 상관관계를 확인했다."}, {"n": 8, "en": "However, most of this correlation disappeared once researchers corrected for the fact that many coffee drinkers also smoke.", "ko": "그러나 연구자들이 커피를 마시는 많은 사람들이 흡연도 한다는 사실에 대해 수정을 하자 이러한 상관관계의 대부분은 사라졌다."}, {"n": 9, "en": "If the confounding factors are known, it is often possible to correct for them.", "ko": "교란 변수들이 알려져 있다면 그것들을 수정하는 것이 종종 가능하다."}, {"n": 10, "en": "However, if they are unknown, they will undermine the reliability of the causal conclusions we draw from epidemiological surveys.", "ko": "그러나 그것들이 알려져 있지 않다면, 그것들은 우리가 역학 조사로부터 도출하는 인과적 결론의 신뢰성을 손상시킬 것이다."}]}, {"id": "2311-32", "short": "23년 11월 32번", "group": "23년 11월", "num": 32, "topic_ko": "사건 후 접한 정보가 목격자의 기억에 통합되는 과정", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "사건 후 정보는 기억에 영향을 주며, 기억이 약할수록 쉽게 통합됨"}, {"n": 2, "label": "전개", "from": 3, "to": 4, "summary_ko": "확인할 기억 정보가 줄면 새 정보가 거부되지 않고 원래 경험의 일부가 됨"}, {"n": 3, "label": "결말", "from": 5, "to": 8, "summary_ko": "이 과정은 흔히 무의식적이며, 출처를 잊게 되고 잘못된 정보는 어디서나 접할 수 있음"}], "gloss": [{"w": "encounter", "m": "~와 마주치다", "form": "encountered", "note": "동사 encounter의 과거분사형(앞의 information을 꾸며 줌)"}, {"w": "influence", "m": "~에 영향을 미치다"}, {"w": "subsequent", "m": "이후의, 다음의"}, {"w": "integrate", "m": "통합되다, 합쳐지다", "form": "integrated", "note": "동사 integrate의 과거분사형(4번 문장 it may be integrated, 수동의 의미)"}, {"w": "witness", "m": "목격자"}, {"w": "encode", "m": "부호화하다(기억으로 저장하다)", "form": "encoded", "note": "동사 encode의 과거분사형(수동의 의미)"}, {"w": "degrade", "m": "저하시키다, 떨어뜨리다", "form": "degraded", "note": "동사 degrade의 과거분사형(현재완료 have degraded의 일부)"}, {"w": "validity", "m": "타당성, 유효성"}, {"w": "misinformation", "m": "잘못된 정보"}, {"w": "reject", "m": "거부하다", "form": "rejected", "note": "동사 reject의 과거분사형(수동의 의미)"}, {"w": "unconscious", "m": "무의식적인"}, {"w": "explicit", "m": "명시적인, 분명한"}, {"w": "source", "m": "출처"}, {"w": "investigator", "m": "수사관", "form": "investigators", "note": "명사 investigator의 복수형"}], "qa": [{"chunk": 1, "q": "사건 후에 접한 외부 정보가 목격자의 기억에 쉽게 통합되는 경우는?", "opts": ["사건이 불충분하게 부호화되었거나 먼 과거의 일인 경우", "목격자가 사건 직후 내용을 꼼꼼히 기록해 둔 경우", "사건을 여러 번 반복해서 떠올린 경우"], "ans": 0, "why": ["2번 문장이 근거이다.", "사건이 poorly encoded(불충분하게 부호화됨)였거나 먼 과거의 일이면, 시간과 망각이 원래 기억을 약하게 만든다.", "직후에 기록해 두거나 반복해 떠올린다는 내용은 지문에 없다."], "ev_en": "External information can easily integrate into a witness\u2019s memory, especially if the event was poorly encoded or the memory is from a distant event, in which case time and forgetting have degraded the original memory.", "ev_ko": "특히 사건이 불충분하게 부호화되었거나, 그 기억이 시간과 망각이 원래의 기억을 저하시켜 온 먼 사건으로부터 온 것이라면, 외부 정보는 목격자의 기억에 쉽게 통합될 수 있다."}, {"chunk": 2, "q": "사건 후의 잘못된 정보가 덜 거부되는 이유로 알맞은 것은?", "opts": ["목격자가 새 정보를 일부러 믿으려고 하기 때문", "그 정보가 항상 법정에서만 주어지기 때문", "기억 속에 그 정보의 유효성을 확인할 정보가 줄어들었기 때문"], "ans": 2, "why": ["3번 문장이 근거이다.", "확인에 쓸 수 있는 기억 정보가 줄면 새 정보가 거부될 가능성이 낮아진다.", "목격자가 일부러 믿는다는 내용은 없고, 5번 문장에서는 오히려 흔히 무의식적이라고 한다.", "법정은 8번 문장에서 잘못된 정보를 접하는 여러 곳 중 하나로 나올 뿐이다."], "ev_en": "With reduced information available in memory with which to confirm the validity of post\u2011event misinformation, it is less likely that this new information will be rejected.", "ev_ko": "사건 후의 잘못된 정보의 유효성을 확인하기 위해 기억에서 사용할 수 있는 줄어든 정보를 가지면, 이 새로운 정보가 덜 거부될 듯하다."}, {"chunk": 3, "q": "정보가 기억에 통합되는 과정의 특징으로 알맞은 것은?", "opts": ["흔히 무의식적이며, 시간이 지나면 출처조차 모를 수 있다.", "대개 목격자가 알고 있는 가운데 진행되며 출처도 정확히 남는다.", "법정에서만 일어나며 다른 곳에서는 일어나지 않는다."], "ans": 0, "why": ["5번 문장은 이 과정이 explicit(명시적인)일 수 있지만 often unconscious(흔히 무의식적인)라고 한다.", "7번 문장에서 시간이 지나면 새 기억의 출처조차 모를 수 있다고 한다.", "8번 문장에서 출처는 토론, 소셜 미디어, 면담, 법정 등 어디서나 접할 수 있다고 하므로 법정에만 한정되지 않는다."], "ev_en": "This process can be explicit (i.e., the witness knows it is happening), but it is often unconscious.", "ev_ko": "이 과정은 명시적일 수 있지만(즉, 목격자는 그것이 일어나고 있다는 것을 알고 있다), 그것은 흔히 무의식적이다."}], "tf": [{"s": "사건 후 접한 정보는 이후의 기억에 영향을 줄 수 있다.", "t": true, "why": ["1번 문장 그대로의 내용이다.", "information encountered after an event(사건 후에 마주친 정보)가 subsequent remembering(이후의 기억하기)에 영향을 줄 수 있다는 뜻이다.", "글 전체의 중심 내용이기도 하다."], "ev_en": "Information encountered after an event can influence subsequent remembering.", "ev_ko": "사건 후에 마주친 정보는 이후의 기억하는 것에 영향을 미칠 수 있다."}, {"s": "잘못된 정보의 출처는 오직 법정에서만 마주칠 수 있다.", "t": false, "why": ["범위가 좁혀진 진술이다.", "8번 문장은 잘못된 정보의 출처를 다른 목격자들과의 토론, 소셜 미디어 조사, 수사관과의 면담, 심지어 법정에서까지(even in court) 어디에서나 마주칠 수 있다고 한다.", "즉 법정은 여러 곳 중 하나일 뿐이다."], "ev_en": "Sources of misinformation in forensic contexts can be encountered anywhere, from discussions with other witnesses to social media searches to multiple interviews with investigators or other legal professionals, and even in court.", "ev_ko": "법정의 상황에서의 잘못된 정보의 출처는 다른 목격자들과의 토론에서부터 소셜 미디어 조사들, 수사관 또는 기타 법률 전문가들과의 다중 인터뷰들, 심지어 법정에서까지 어디에서나 마주쳐질 수 있다."}, {"s": "외부 정보가 목격자의 현재 생각과 맞으면 원래 경험의 일부로 통합될 수 있다.", "t": true, "why": ["4번 문장의 내용이다.", "현재 생각과 맞고 이해되는 이야기를 만드는 데 쓰일 수 있을 때 통합된다."], "ev_en": "Instead, especially when it fits the witness\u2019s current thinking and can be used to create a story that makes sense to him or her, it may be integrated as part of the original experience.", "ev_ko": "대신에, 특히 그것이 목격자의 현재 생각과 맞고 그 또는 그녀에게 이해되는 하나의 이야기를 만드는 데 사용될 수 있을 때, 그것은 원래 경험의 일부로서 통합될 수 있다."}, {"s": "목격자는 사건을 다르게 생각하게 될 때 대개 그 변화를 분명히 의식하고 있다.", "t": false, "why": ["지문과 반대이다.", "6번 문장은 목격자가 의식하지 못한 채(without awareness) 그 사건에 대해 다르게 생각하게 될 수 있다고 한다."], "ev_en": "That is, the witness might find himself or herself thinking about the event differently without awareness.", "ev_ko": "즉, 목격자는 의식하지 못한 채 그 사건에 대해 다르게 생각하는 그 자신 또는 그녀 자신을 발견할지도 모른다."}, {"s": "시간이 지나면 목격자는 새 기억을 만든 정보의 출처조차 모를 수 있다.", "t": true, "why": ["7번 문장의 내용이다.", "may not even know the source(출처조차 모를지도 모른다)는 시간이 지나면 새 기억이 어디서 왔는지 잊을 수 있다는 뜻이다."], "ev_en": "Over time, the witness may not even know the source of information that led to the (new) memory.", "ev_ko": "시간이 지남에 따라, 목격자는 (새로운) 기억으로 이끄는 정보의 출처조차 모를지도 모른다."}], "flow": {"fixed": "사건이 끝난 뒤에 접하게 된 정보는 이후 그 사건을 기억해 내는 데 영향을 줄 수 있다.", "order": ["특히 원래 기억이 불충분했거나 오래전 일이라면 사건 후 외부 정보가 쉽게 섞여 들어가고, 새 정보가 틀렸는지 확인할 기억 속 재료도 줄어 잘 걸러지지 않는다.", "게다가 이런 섞임은 대개 본인이 알아채지 못하는 사이에 일어나서, 목격자는 자기도 모르게 그 사건을 다르게 생각하게 되기도 한다.", "그렇게 알아채지 못한 채 시간이 지나면 목격자는 새 기억의 출처조차 모르게 되고, 이런 잘못된 정보는 토론, 소셜 미디어, 면담, 법정 등 어디서든 접할 수 있다."], "clue": ["'특히'와 '사건 후 외부 정보'가 첫 덩어리의 사건 후 정보를 이어받아, 기억이 약할 때 더 쉽게 섞임을 설명함", "'이런 섞임'이 앞에서 말한 통합 과정을 가리키고 '게다가'로 무의식이라는 특징을 덧붙임", "'그렇게 알아채지 못한 채'가 앞 덩어리의 무의식적 과정을 그대로 받아, 시간이 지난 뒤의 결과와 마무리를 말함"], "why": ["사건 후 정보가 기억에 영향을 줌", "기억이 약하면 쉽게 섞여 들어가 걸러지지 않음", "이 과정은 무의식적임", "결국 출처를 잊고 잘못된 정보는 어디서나 접함"], "cards": ["게다가 이런 섞임은 대개 본인이 알아채지 못하는 사이에 일어나서, 목격자는 자기도 모르게 그 사건을 다르게 생각하게 되기도 한다.", "그렇게 알아채지 못한 채 시간이 지나면 목격자는 새 기억의 출처조차 모르게 되고, 이런 잘못된 정보는 토론, 소셜 미디어, 면담, 법정 등 어디서든 접할 수 있다.", "특히 원래 기억이 불충분했거나 오래전 일이라면 사건 후 외부 정보가 쉽게 섞여 들어가고, 새 정보가 틀렸는지 확인할 기억 속 재료도 줄어 잘 걸러지지 않는다."], "answer": [2, 0, 1]}, "sents": [{"n": 1, "en": "Information encountered after an event can influence subsequent remembering.", "ko": "사건 후에 마주친 정보는 이후의 기억하는 것에 영향을 미칠 수 있다."}, {"n": 2, "en": "External information can easily integrate into a witness\u2019s memory, especially if the event was poorly encoded or the memory is from a distant event, in which case time and forgetting have degraded the original memory.", "ko": "특히 사건이 불충분하게 부호화되었거나, 그 기억이 시간과 망각이 원래의 기억을 저하시켜 온 먼 사건으로부터 온 것이라면, 외부 정보는 목격자의 기억에 쉽게 통합될 수 있다."}, {"n": 3, "en": "With reduced information available in memory with which to confirm the validity of post\u2011event misinformation, it is less likely that this new information will be rejected.", "ko": "사건 후의 잘못된 정보의 유효성을 확인하기 위해 기억에서 사용할 수 있는 줄어든 정보를 가지면, 이 새로운 정보가 덜 거부될 듯하다."}, {"n": 4, "en": "Instead, especially when it fits the witness\u2019s current thinking and can be used to create a story that makes sense to him or her, it may be integrated as part of the original experience.", "ko": "대신에, 특히 그것이 목격자의 현재 생각과 맞고 그 또는 그녀에게 이해되는 하나의 이야기를 만드는 데 사용될 수 있을 때, 그것은 원래 경험의 일부로서 통합될 수 있다."}, {"n": 5, "en": "This process can be explicit (i.e., the witness knows it is happening), but it is often unconscious.", "ko": "이 과정은 명시적일 수 있지만(즉, 목격자는 그것이 일어나고 있다는 것을 알고 있다), 그것은 흔히 무의식적이다."}, {"n": 6, "en": "That is, the witness might find himself or herself thinking about the event differently without awareness.", "ko": "즉, 목격자는 의식하지 못한 채 그 사건에 대해 다르게 생각하는 그 자신 또는 그녀 자신을 발견할지도 모른다."}, {"n": 7, "en": "Over time, the witness may not even know the source of information that led to the (new) memory.", "ko": "시간이 지남에 따라, 목격자는 (새로운) 기억으로 이끄는 정보의 출처조차 모를지도 모른다."}, {"n": 8, "en": "Sources of misinformation in forensic contexts can be encountered anywhere, from discussions with other witnesses to social media searches to multiple interviews with investigators or other legal professionals, and even in court.", "ko": "법정의 상황에서의 잘못된 정보의 출처는 다른 목격자들과의 토론에서부터 소셜 미디어 조사들, 수사관 또는 기타 법률 전문가들과의 다중 인터뷰들, 심지어 법정에서까지 어디에서나 마주쳐질 수 있다."}]}, {"id": "2311-33", "short": "23년 11월 33번", "group": "23년 11월", "num": 33, "topic_ko": "상관관계의 힘과 인과 설명 시도의 한계", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "상관관계는 통찰이 명확해 강력하지만, 인과를 끌어들이면 가려짐"}, {"n": 2, "label": "전개", "from": 3, "to": 7, "summary_ko": "주황색 차 사례에서 우리는 이유를 추측하다 경쟁적 인과 가설에 빠짐"}, {"n": 3, "label": "결말", "from": 8, "to": 11, "summary_ko": "설명 시도는 상황을 흐리고 인과는 보이기 어려우므로 이유 설명을 삼가는 것이 좋음"}], "gloss": [{"w": "correlation", "m": "상관관계", "form": "Correlations", "note": "명사 correlation의 복수형"}, {"w": "insight", "m": "통찰력", "form": "insights", "note": "명사 insight의 복수형"}, {"w": "causality", "m": "인과 관계"}, {"w": "statistician", "m": "통계학자", "form": "statisticians", "note": "명사 statistician의 복수형"}, {"w": "defect", "m": "결함", "form": "defects", "note": "명사 defect의 복수형"}, {"w": "enthusiast", "m": "애호가", "form": "enthusiasts", "note": "명사 enthusiast의 복수형"}, {"w": "noticeable", "m": "눈에 띄는"}, {"w": "hypothesis", "m": "가설", "form": "hypotheses", "note": "명사 hypothesis의 복수형(-is가 -es로 바뀜)"}, {"w": "illuminate", "m": "설명하다, 밝히다"}, {"w": "cloudy", "m": "흐린", "form": "cloudier", "note": "형용사 cloudy의 비교급"}, {"w": "mathematically", "m": "수학적으로"}, {"w": "causal", "m": "인과의"}, {"w": "hold off from", "m": "~을 삼가다, 미루다"}, {"w": "resell", "m": "재판매하다", "form": "resold", "note": "동사 resell의 과거분사형(수동의 의미)"}], "qa": [{"chunk": 1, "q": "지문에서 상관관계가 강력하다고 한 이유는?", "opts": ["제공하는 통찰이 비교적 명확하기 때문", "원인과 결과를 정확히 밝혀 주기 때문", "수학 없이도 누구나 계산할 수 있기 때문"], "ans": 0, "why": ["1번 문장이 근거이다.", "the insights they offer are relatively clear, 즉 상관관계가 주는 통찰이 비교적 명확하기 때문이다.", "원인과 결과를 밝혀 준다는 내용은 없고, 오히려 인과를 끌어들이면 통찰이 가려진다고 한다.", "수학 없이도 누구나 계산할 수 있다는 내용도 없다. 9번 문장은 상관관계를 수학적으로 보여 줄 수 있다고만 한다."], "ev_en": "Correlations are powerful because the insights they offer are relatively clear.", "ev_ko": "상관관계는 그것들이 제공하는 통찰력이 비교적 명확하기 때문에 강력하다."}, {"chunk": 2, "q": "주황색 차 사례에서 이 결과를 읽은 우리가 곧바로 하게 되는 일은?", "opts": ["이유를 추측하다가 서로 경쟁하는 인과 가설에 빠진다.", "통계학자에게 더 많은 데이터를 요청한다.", "상관관계 분석 결과를 믿지 않고 무시한다."], "ans": 0, "why": ["7번 문장이 근거이다.", "5~6번 문장에서 차 주인이 관리를 잘해서인지, 눈에 띄어 사고가 적어서인지 이유를 따지게 된다.", "데이터를 더 요청하거나 결과를 무시한다는 내용은 없다."], "ev_en": "Quickly we are caught in a web of competing causal hypotheses.", "ev_ko": "곧 우리는 경쟁적인 인과 가설의 함정에 빠진다."}, {"chunk": 3, "q": "글쓴이의 결론으로 알맞은 것은?", "opts": ["인과 관계를 먼저 밝힌 뒤에 상관관계를 활용해야 한다.", "상관관계는 수학적으로 보일 수 없으므로 믿기 어렵다.", "상관관계의 배후 이유를 설명하려 하지 않는 것이 좋다."], "ans": 2, "why": ["11번 문장이 근거이다.", "hold off from trying to explain the reason은 이유를 설명하려는 것을 삼가라는 뜻이다.", "9번 문장에서 상관관계는 수학적으로 보여 줄 수 있다고 하므로 \u2018상관관계는 수학적으로 보일 수 없다\u2019는 진술은 틀리다.", "\u2018인과 관계를 먼저 밝힌 뒤 활용해야 한다\u2019는 내용도 지문에 없고, 오히려 인과를 끌어들이면 통찰이 가려진다(2번 문장)고 한다."], "ev_en": "So we would do well to hold off from trying to explain the reason behind the correlations.", "ev_ko": "따라서 우리는 상관관계의 배후에 있는 이유를 설명하려 하지 않는 것이 좋다."}], "tf": [{"s": "한 중고차 딜러가 경매 차량 중 문제가 생길 만한 차를 예측하려고 통계학자에게 데이터를 제공했다.", "t": true, "why": ["3번 문장의 내용이다."], "ev_en": "For instance, a used\u2011car dealer supplied data to statisticians to predict which of the vehicles available for purchase at an auction were likely to have problems.", "ev_ko": "예를 들어, 한 중고차 딜러가 경매에서 구입할 수 있는 차량들 중 어떤 차량에 문제가 발생할 가능성이 있는지를 예측하기 위한 데이터를 통계학자들에게 제공했다."}, {"s": "상관관계 분석에서 주황색 차는 결함이 있을 가능성이 훨씬 높게 나타났다.", "t": false, "why": ["결과가 반대로 바뀐 진술이다.", "분석은 주황색 차가 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."], "ev_en": "A correlation analysis showed that orange\u2011colored cars were far less likely to have defects.", "ev_ko": "한 상관관계 분석은 주황색 차들이 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."}, {"s": "주황색 차가 도로에서 더 눈에 띄어 사고가 적다는 것은 지문이 제시한 가능한 설명 중 하나이다.", "t": true, "why": ["6번 문장에서 가능한 이유로 제시된 내용이다.", "이 설명으로 재판매 때 상태가 더 좋다는 결과를 풀이해 볼 수 있다."], "ev_en": "Or, is it because orange\u2011colored cars are more noticeable on the road and therefore less likely to be in accidents, so they\u2019re in better condition when resold?", "ev_ko": "아니면, 주황색 차들이 도로에서 더 눈에 띄고, 그래서 사고가 날 가능성이 적어 재판매될 때 그것들이 상태가 더 좋은 것이기 때문인가?"}, {"s": "글쓴이는 인과 관계도 상관관계만큼 쉽게 수학적으로 보여 줄 수 있다고 말한다.", "t": false, "why": ["지문과 반대이다.", "9번 문장은 Correlations exist; we can show them mathematically(상관관계는 존재하며, 우리는 그것을 수학적으로 보여 줄 수 있다)고 한다.", "반면 10번 문장은 인과 관계에 대해서는 쉽게 똑같이 할 수 없다고 한다."], "ev_en": "We can\u2019t easily do the same for causal links.", "ev_ko": "우리는 인과 관계에 대해서는 쉽게 똑같이 할 수 없다."}, {"s": "인과 관계로 설명하려는 시도는 오히려 상황을 더 흐리게 만들 뿐이다.", "t": true, "why": ["8번 문장의 내용이다.", "this way는 앞에서 말한 인과적 이유를 설명하려는 방식을 가리킨다.", "그런 시도는 상황을 cloudier(더 흐린, 형용사 cloudy의 비교급)하게, 즉 더 흐리게 만들 뿐이라고 한다."], "ev_en": "But our attempts to illuminate things this way only make them cloudier.", "ev_ko": "하지만 이런 식으로 무언가를 설명하려는 우리의 시도는 그것들을 더 흐리게 만들 뿐이다."}], "flow": {"fixed": "상관관계는 그것이 주는 통찰이 비교적 분명해서 강력하지만, 인과 관계를 끌어들이면 그 통찰이 종종 가려진다.", "order": ["예를 들어 한 중고차 딜러의 데이터를 분석했더니, 주황색 차가 결함이 있을 가능성이 훨씬 적다는 상관관계가 나타났다.", "그런데 이 결과를 보면 우리는 곧바로 이유를 궁리하게 되어, 차주가 차를 잘 관리해서인지 눈에 띄어 사고가 적어서인지 하는 경쟁하는 가설에 빠져든다.", "하지만 그렇게 설명하려 할수록 오히려 더 흐려지고, 상관관계와 달리 인과는 쉽게 보여 줄 수 없으므로 이유를 설명하려 하지 않는 편이 낫다."], "clue": ["'예를 들어'로 첫 덩어리의 주장을 구체적인 사례로 보여 줌", "'이 결과'가 앞 사례의 분석 결과를 가리키고 '그런데'로 우리의 반응이 이어짐", "'그렇게 설명하려 할수록'이 앞의 가설 세우기를 받아 결론으로 마무리함"], "why": ["상관관계는 명확하지만 인과를 끌어들이면 가려짐", "주황색 차 사례", "결과를 보면 곧 경쟁하는 가설에 빠짐", "설명하려 하지 말고 이유 설명을 삼가는 것이 좋음"], "cards": ["하지만 그렇게 설명하려 할수록 오히려 더 흐려지고, 상관관계와 달리 인과는 쉽게 보여 줄 수 없으므로 이유를 설명하려 하지 않는 편이 낫다.", "그런데 이 결과를 보면 우리는 곧바로 이유를 궁리하게 되어, 차주가 차를 잘 관리해서인지 눈에 띄어 사고가 적어서인지 하는 경쟁하는 가설에 빠져든다.", "예를 들어 한 중고차 딜러의 데이터를 분석했더니, 주황색 차가 결함이 있을 가능성이 훨씬 적다는 상관관계가 나타났다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Correlations are powerful because the insights they offer are relatively clear.", "ko": "상관관계는 그것들이 제공하는 통찰력이 비교적 명확하기 때문에 강력하다."}, {"n": 2, "en": "These insights are often covered up when we bring causality back into the picture.", "ko": "이러한 통찰력은 종종 우리가 인과 관계를 그 상황으로 다시 가져올 때 가려진다."}, {"n": 3, "en": "For instance, a used\u2011car dealer supplied data to statisticians to predict which of the vehicles available for purchase at an auction were likely to have problems.", "ko": "예를 들어, 한 중고차 딜러가 경매에서 구입할 수 있는 차량들 중 어떤 차량에 문제가 발생할 가능성이 있는지를 예측하기 위한 데이터를 통계학자들에게 제공했다."}, {"n": 4, "en": "A correlation analysis showed that orange\u2011colored cars were far less likely to have defects.", "ko": "한 상관관계 분석은 주황색 차들이 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."}, {"n": 5, "en": "Even as we read this, we already think about why it might be so: Are orange\u2011colored car owners likely to be car enthusiasts and take better care of their vehicles?", "ko": "심지어 우리가 이것을 읽으면서도, 우리는 이미 왜 그럴지에 대해 생각한다. 주황색 차를 소유한 사람들이 자동차 애호가여서 그들의 차량을 더 잘 관리할 가능성이 있는가?"}, {"n": 6, "en": "Or, is it because orange\u2011colored cars are more noticeable on the road and therefore less likely to be in accidents, so they\u2019re in better condition when resold?", "ko": "아니면, 주황색 차들이 도로에서 더 눈에 띄고, 그래서 사고가 날 가능성이 적어 재판매될 때 그것들이 상태가 더 좋은 것이기 때문인가?"}, {"n": 7, "en": "Quickly we are caught in a web of competing causal hypotheses.", "ko": "곧 우리는 경쟁적인 인과 가설의 함정에 빠진다."}, {"n": 8, "en": "But our attempts to illuminate things this way only make them cloudier.", "ko": "하지만 이런 식으로 무언가를 설명하려는 우리의 시도는 그것들을 더 흐리게 만들 뿐이다."}, {"n": 9, "en": "Correlations exist; we can show them mathematically.", "ko": "상관관계는 존재하며 우리는 그것들을 수학적으로 보여 줄 수 있다."}, {"n": 10, "en": "We can\u2019t easily do the same for causal links.", "ko": "우리는 인과 관계에 대해서는 쉽게 똑같이 할 수 없다."}, {"n": 11, "en": "So we would do well to hold off from trying to explain the reason behind the correlations.", "ko": "따라서 우리는 상관관계의 배후에 있는 이유를 설명하려 하지 않는 것이 좋다."}]}, {"id": "2311-34", "short": "23년 11월 34번", "group": "23년 11월", "num": 34, "topic_ko": "동물 종의 수명이 야생 생존 시간에 의해 결정되는 원리", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "야생 쥐는 외부 원인으로 일찍 죽어 평균 2년 넘게 살지 못함"}, {"n": 2, "label": "중심", "from": 4, "to": 5, "summary_ko": "종의 평균 수명은 야생에서 생존할 수 있는 평균 시간에 의해 결정됨"}, {"n": 3, "label": "마무리", "from": 6, "to": 8, "summary_ko": "박쥐는 날 수 있어 위험을 피하고 먹이를 잘 찾아 오래 사는 변화가 유용했음"}], "gloss": [{"w": "life span", "m": "수명"}, {"w": "starvation", "m": "굶주림"}, {"w": "predator", "m": "포식자", "form": "predators", "note": "명사 predator의 복수형"}, {"w": "external", "m": "외부의"}, {"w": "internal", "m": "내부의"}, {"w": "aging", "m": "노화"}, {"w": "species", "m": "(생물) 종"}, {"w": "determine", "m": "결정하다", "form": "determined", "note": "동사 determine의 과거분사형(is determined, 수동태)"}, {"w": "escape", "m": "도망치다, 벗어나다"}, {"w": "distance", "m": "거리", "form": "distances", "note": "명사 distance의 복수형"}, {"w": "genetic", "m": "유전적인"}, {"w": "flee", "m": "달아나다"}, {"w": "mouse", "m": "쥐", "form": "mice", "note": "명사 mouse의 불규칙 복수형"}, {"w": "bat", "m": "박쥐", "form": "bats", "note": "명사 bat의 복수형"}], "qa": [{"chunk": 1, "q": "지문에 따르면 야생 쥐가 죽는 주된 원인은?", "opts": ["질병, 굶주림, 포식자와 같은 외부적인 원인", "노화와 같은 내부적인 원인", "유전적 변화로 인한 원인"], "ans": 0, "why": ["2번 문장이 근거이다.", "쥐는 disease(질병), starvation(굶주림), predators(포식자) 같은 외부 원인으로 죽는다.", "노화 같은 내부 원인 때문이 아니라고 분명히 말한다.", "유전적 변화는 박쥐 이야기에서 나오는 내용이다."], "ev_en": "They die from external causes, such as disease, starvation, or predators, not due to internal causes, such as aging.", "ev_ko": "그들은 노화와 같은 \u2018내부적인 원인들\u2019 때문이 아니라 질병, 굶주림 또는 포식자와 같은 \u2018외부적인 원인들\u2019로 죽는다."}, {"chunk": 2, "q": "동물 종의 평균 수명을 결정하는 것은?", "opts": ["그 종의 몸집 크기", "그 종이 야생에서 생존할 수 있는 평균 시간", "그 종이 먹는 먹이의 양"], "ans": 1, "why": ["4번 문장이 근거이다.", "평균 수명이나 노화 속도는 야생에서 생존할 수 있는 평균 시간에 의해 정해진다.", "몸집이나 먹이의 양은 지문에 나오지 않는다."], "ev_en": "Now we have arrived at an important point: The average life span of an animal species, or the rate at which it ages, is determined by the average time that this animal species can survive in the wild.", "ev_ko": "이제 우리는 중요한 지점에 도달했다. 동물 종의 평균 수명, 또는 그것이 노화하는 속도는 이 동물 종이 야생에서 생존할 수 있는 평균 시간에 의해 결정된다."}, {"chunk": 3, "q": "박쥐가 쥐보다 오래 살 수 있는 이유로 알맞은 것은?", "opts": ["쥐보다 새끼를 더 많이 낳기 때문", "날 수 있어서 위험에서 훨씬 더 빨리 도망칠 수 있기 때문", "노화가 전혀 일어나지 않는 몸을 가졌기 때문"], "ans": 1, "why": ["6번 문장이 근거이다.", "박쥐는 쥐와 달리 날 수 있어서 위험에서 훨씬 더 빨리 도망칠 수 있다(escape from danger much faster).", "7번 문장은 날개 덕분에 더 긴 거리를 이동하고 먹이도 더 잘 찾는다고 덧붙인다.", "새끼를 더 많이 낳는다는 내용도, 노화가 전혀 일어나지 않는다는 내용도 지문에 없다."], "ev_en": "In contrast to mice, bats can fly, which is why they can escape from danger much faster.", "ev_ko": "쥐와 대조적으로 박쥐는 날 수 있고, 이것은 그들이 위험에서 훨씬 더 빨리 도망칠 수 있는 이유이다."}], "tf": [{"s": "야생의 쥐는 대부분 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다.", "t": true, "why": ["1번 문장의 내용이다.", "쥐의 수명 2년이 끝나기 전에 대부분 잡아먹히거나 죽는다는 뜻이다."], "ev_en": "Most mice in the wild are eaten or die before their life span of two years is over.", "ev_ko": "야생에 있는 대부분의 쥐들은 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다."}, {"s": "박쥐도 쥐와 비슷하게 2년 안팎까지만 살 수 있다.", "t": false, "why": ["수치가 바뀐 진술이다.", "5번 문장은 박쥐가 30세까지 살 수 있다고 한다."], "ev_en": "That explains why a bat can live to be 30 years old.", "ev_ko": "그것은 왜 박쥐가 30세까지 살 수 있는지를 설명해 준다."}, {"s": "박쥐는 날개 덕분에 더 긴 거리를 이동하고 먹이를 더 잘 찾을 수 있다.", "t": true, "why": ["7번 문장의 내용이다.", "thanks to their wings(날개 덕분에)가 이유이고, longer distances(더 긴 거리)와 find food(먹이를 찾다)가 결과이다."], "ev_en": "Thanks to their wings, bats can also cover longer distances and are better able to find food.", "ev_ko": "그들의 날개 덕분에, 박쥐들은 또한 더 긴 거리를 이동할 수 있고 먹이를 더 잘 찾을 수 있다."}, {"s": "자연은 쥐가 평균적으로 2년 넘게 살도록 만들었다.", "t": false, "why": ["방향이 반대로 바뀐 진술이다.", "3번 문장은 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만들었다고 한다(no longer than two years)."], "ev_en": "That is why nature has made mice to live, on average, for no longer than two years.", "ev_ko": "그것이 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만든 이유이다."}, {"s": "박쥐가 더 오래 사는 것을 가능하게 한 과거의 유전적 변화는 유용했다.", "t": true, "why": ["8번 문장의 내용이다.", "박쥐는 위험에서 도망치고 먹이를 찾고 생존하는 일을 쥐보다 훨씬 잘하기 때문이다.", "그래서 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다는 뜻이다."], "ev_en": "Every genetic change in the past that made it possible for a bat to live longer was useful, because bats are much better able than mice to flee from danger, find food, and survive.", "ev_ko": "박쥐가 더 오래 사는 것을 가능하게 해 준 과거의 모든 유전적 변화는 박쥐가 쥐보다 위험으로부터 도망치고, 먹이를 찾고, 생존하는 것을 훨씬 더 잘할 수 있기 때문에 유용했다."}], "flow": {"fixed": "야생의 쥐는 대부분 질병, 굶주림, 포식자 같은 외부 원인으로 일찍 죽기 때문에, 자연은 쥐를 평균 2년 넘게 살지 못하게 만들었다.", "order": ["여기서 중요한 점은 한 동물 종의 평균 수명이나 노화 속도가 그 종이 야생에서 생존할 수 있는 평균 시간에 따라 정해진다는 것이다.", "이것이 박쥐가 30세까지 살 수 있는 이유를 설명해 주는데, 쥐와 달리 박쥐는 날 수 있어서 위험에서 훨씬 빨리 벗어난다.", "게다가 날개 덕분에 더 멀리 이동하며 먹이도 더 잘 찾으므로, 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다."], "clue": ["'여기서 중요한 점'으로 쥐 사례에서 일반 원리를 끌어냄", "'이것'이 앞의 원리를 가리키며 박쥐 사례에 적용함", "'게다가'로 박쥐의 장점을 더하고 유전적 변화의 유용함으로 결론을 맺음"], "why": ["쥐는 외부 원인으로 일찍 죽어 수명이 짧음", "종의 수명은 야생 생존 시간이 결정", "그래서 날 수 있는 박쥐는 위험을 잘 피함", "먹이도 잘 찾아 오래 사는 변화가 유용했음"], "cards": ["게다가 날개 덕분에 더 멀리 이동하며 먹이도 더 잘 찾으므로, 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다.", "이것이 박쥐가 30세까지 살 수 있는 이유를 설명해 주는데, 쥐와 달리 박쥐는 날 수 있어서 위험에서 훨씬 빨리 벗어난다.", "여기서 중요한 점은 한 동물 종의 평균 수명이나 노화 속도가 그 종이 야생에서 생존할 수 있는 평균 시간에 따라 정해진다는 것이다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Most mice in the wild are eaten or die before their life span of two years is over.", "ko": "야생에 있는 대부분의 쥐들은 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다."}, {"n": 2, "en": "They die from external causes, such as disease, starvation, or predators, not due to internal causes, such as aging.", "ko": "그들은 노화와 같은 \u2018내부적인 원인들\u2019 때문이 아니라 질병, 굶주림 또는 포식자와 같은 \u2018외부적인 원인들\u2019로 죽는다."}, {"n": 3, "en": "That is why nature has made mice to live, on average, for no longer than two years.", "ko": "그것이 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만든 이유이다."}, {"n": 4, "en": "Now we have arrived at an important point: The average life span of an animal species, or the rate at which it ages, is determined by the average time that this animal species can survive in the wild.", "ko": "이제 우리는 중요한 지점에 도달했다. 동물 종의 평균 수명, 또는 그것이 노화하는 속도는 이 동물 종이 야생에서 생존할 수 있는 평균 시간에 의해 결정된다."}, {"n": 5, "en": "That explains why a bat can live to be 30 years old.", "ko": "그것은 왜 박쥐가 30세까지 살 수 있는지를 설명해 준다."}, {"n": 6, "en": "In contrast to mice, bats can fly, which is why they can escape from danger much faster.", "ko": "쥐와 대조적으로 박쥐는 날 수 있고, 이것은 그들이 위험에서 훨씬 더 빨리 도망칠 수 있는 이유이다."}, {"n": 7, "en": "Thanks to their wings, bats can also cover longer distances and are better able to find food.", "ko": "그들의 날개 덕분에, 박쥐들은 또한 더 긴 거리를 이동할 수 있고 먹이를 더 잘 찾을 수 있다."}, {"n": 8, "en": "Every genetic change in the past that made it possible for a bat to live longer was useful, because bats are much better able than mice to flee from danger, find food, and survive.", "ko": "박쥐가 더 오래 사는 것을 가능하게 해 준 과거의 모든 유전적 변화는 박쥐가 쥐보다 위험으로부터 도망치고, 먹이를 찾고, 생존하는 것을 훨씬 더 잘할 수 있기 때문에 유용했다."}]}, {"id": "2311-37", "short": "23년 11월 37번", "group": "23년 11월", "num": 37, "topic_ko": "무작위 추출의 한계와 전체 데이터의 자유로움", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "무작위 추출법은 디지털 시대 이전에 좋은 지름길이었음"}, {"n": 2, "label": "반전", "from": 3, "to": 4, "summary_ko": "추출은 정보를 잃게 하지만 전체 데이터는 더 큰 탐색의 자유를 줌"}, {"n": 3, "label": "전개와 결말", "from": 5, "to": 9, "summary_ko": "라이트 필드 카메라처럼 모든 정보를 담으면 나중에 초점을 정할 수 있고 재사용성이 높음"}], "gloss": [{"w": "random sampling", "m": "무작위 추출법 (sample: 표본을 뽑다, 추출하다)"}, {"w": "shortcut", "m": "지름길"}, {"w": "pre\u2011digital", "m": "디지털 시대 이전의"}, {"w": "convert", "m": "변환하다", "form": "converting", "note": "동사 convert의 동명사형(주어 역할)"}, {"w": "dataset", "m": "데이터 세트"}, {"w": "explore", "m": "탐색하다"}, {"w": "fitting", "m": "적절한, 알맞은"}, {"w": "capture", "m": "포착하다", "form": "captures", "note": "동사 capture의 3인칭 단수 현재형(주어 which가 단수 camera)"}, {"w": "conventional", "m": "기존의, 전통적인"}, {"w": "ray", "m": "광선", "form": "rays", "note": "명사 ray의 복수형"}, {"w": "focus", "m": "초점을 맞추다"}, {"w": "reusable", "m": "재사용 가능한", "form": "reuseable", "note": "본문의 철자 reuseable은 reusable의 비표준 표기(뜻은 같음)"}, {"w": "shutter", "m": "(카메라) 셔터"}, {"w": "light\u2011field camera", "m": "라이트 필드 카메라(빛의 모든 방향 정보를 담는 카메라)"}], "qa": [{"chunk": 1, "q": "무작위 추출법이 과거에 가졌던 장점은?", "opts": ["디지털 시대 이전에 대규모 데이터 문제의 분석을 가능하게 했다.", "정보를 전혀 잃지 않고 분석할 수 있었다.", "전체 데이터보다 더 정확한 결과를 주었다."], "ans": 0, "why": ["2번 문장이 근거이다.", "무작위 추출은 디지털 시대 이전에 큰 데이터 문제 분석을 가능하게 한 좋은 지름길이었다.", "3번 문장에서 추출할 때는 정보가 손실된다고 하므로 \u2018정보를 전혀 잃지 않고 분석할 수 있었다\u2019는 진술은 틀리다.", "더 정확하다는 내용은 지문에 없다."], "ev_en": "It made analysis of large data problems possible in the pre\u2011digital era.", "ev_ko": "그것은 디지털 시대 이전에 상당한 데이터 문제 분석을 가능하게 했다."}, {"chunk": 2, "q": "전체(또는 전체에 가까운) 데이터 세트를 가질 때의 장점은?", "opts": ["데이터를 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 커진다.", "파일 크기가 더 작아진다.", "분석 시간이 크게 줄어든다."], "ans": 0, "why": ["4번 문장이 근거이다.", "전체 데이터는 탐색하고, 다른 각도에서 보고, 특정 측면을 더 자세히 볼 자유를 준다.", "작은 파일로 변환하면 오히려 데이터 손실이 생긴다는 것이 3번 문장의 내용이므로 파일 크기가 작아지는 것은 장점이 아니다.", "분석 시간이 크게 줄어든다는 내용은 지문에 없다."], "ev_en": "Having the full (or close to the full) dataset provides a lot more freedom to explore, to look at the data from different angles or to look closer at certain aspects of it.", "ev_ko": "전체(또는 전체에 가까운) 데이터 세트를 가지는 것은 탐색하거나 다른 각도에서 데이터를 살펴보거나 그것의 특정 측면들을 더 자세히 보게 하는 자유를 훨씬 더 많이 제공한다."}, {"chunk": 3, "q": "라이트 필드 카메라의 특징으로 알맞은 것은?", "opts": ["셔터를 누르기 전에 초점을 정해야 한다.", "사진사가 나중에 이미지의 어느 요소에 초점을 맞출지 정할 수 있다.", "한 평면의 빛만 포착한다."], "ans": 1, "why": ["6번 문장이 근거이다.", "전체 광선을 담기 때문에 초점은 나중에 정하면 된다.", "\u2018셔터를 누르기 전에 초점을 정해야 한다\u2019는 일반 사진의 특징이고(9번 문장), \u2018한 평면의 빛만 포착한다\u2019는 기존 카메라의 특징이다(5번 문장)."], "ev_en": "The photographers can decide later which element of an image to focus on in the digital file.", "ev_ko": "사진사들은 디지털 파일에서 이미지의 어느 요소에 초점을 맞출지를 나중에 결정할 수 있다."}], "tf": [{"s": "추출을 할 때 정보가 손실되는 것은 디지털 이미지를 더 작은 파일로 바꿀 때 데이터가 손실되는 것과 비슷하다.", "t": true, "why": ["3번 문장의 내용이다."], "ev_en": "But much as converting a digital image or song into a smaller file results in loss of data, information is lost when sampling.", "ev_ko": "그러나 디지털 이미지나 노래를 더 작은 파일로 변환하는 것이 데이터 손실을 유발하는 것과 마찬가지로, 추출을 할 때 정보가 손실된다."}, {"s": "라이트 필드 카메라는 기존 카메라처럼 한 평면의 빛만 포착한다.", "t": false, "why": ["기존 카메라의 특징을 라이트 필드 카메라에 바꿔 붙인 진술이다.", "5번 문장은 not just A but B 구조로, A(한 평면의 빛)뿐 아니라 B(전체 라이트 필드의 광선)도 포착한다는 뜻이다.", "\u2018한 평면의 빛\u2019은 as with conventional cameras(기존 카메라처럼), 즉 기존 카메라의 방식이다.", "공식 해석은 어순 때문에 \u2018한 평면의 빛만 포착할 뿐만 아니라\u2019로 읽혀 헷갈리기 쉬우므로, not just A but B는 \u2018A뿐 아니라 B도\u2019로 이해해야 한다."], "ev_en": "A fitting example may be the light\u2011field camera, which captures not just a single plane of light, as with conventional cameras, but rays from the entire light field, some 11 million of them.", "ev_ko": "라이트 필드 카메라가 적절한 비유가 될 수 있는데, 그것은 기존 카메라처럼 한 평면의 빛만 포착할 뿐만 아니라 약 1,100만 개에 달하는 전체 라이트 필드로부터의 광선들도 포착한다."}, {"s": "라이트 필드 카메라로 찍을 때는 모든 정보를 모아 두더라도 촬영을 시작할 때 초점부터 맞춰야 한다.", "t": false, "why": ["지문과 반대이다.", "7번 문장은 처음에 초점을 맞출 필요가 없다(no need to focus at the beginning)고 한다.", "모든 정보를 수집해 두면 나중에 초점을 맞추는 것이 가능하기 때문이다."], "ev_en": "There is no need to focus at the beginning, since collecting all the information makes it possible to do that afterwards.", "ev_ko": "모든 정보를 수집하는 것은 그것을 나중에 하는 것을 가능하게 만들기 때문에, 처음에 초점을 맞출 필요는 없다."}, {"s": "일반 사진에서는 사진사가 셔터를 누른 뒤에 초점을 맞출 대상을 결정한다.", "t": false, "why": ["시점이 바뀐 진술이다.", "일반 사진에서는 셔터를 누르기 전에 무엇에 초점을 맞출지 결정해야 한다."], "ev_en": "As a result, the information is more \u201creuseable\u201d than ordinary pictures, where the photographer has to decide what to focus on before she presses the shutter.", "ev_ko": "결과적으로 사진사가 셔터를 누르기 전에 그녀가 무엇에 초점을 맞출지를 결정해야 하는 일반 사진들보다 그 정보는 더 \u2018재사용 가능\u2019하다."}, {"s": "라이트 필드 카메라는 전체 라이트 필드의 광선이 포함되기 때문에 모든 데이터에 더 가깝다.", "t": true, "why": ["8번 문장의 내용이다.", "전체 라이트 필드의 광선이 포함되므로 모든 데이터에 더 가깝다는 뜻이다."], "ev_en": "Because rays from the entire light field are included, it is closer to all the data.", "ev_ko": "전체 라이트 필드의 빛이 포함되기 때문에, 그것은 모든 데이터에 더 가깝다."}], "flow": {"fixed": "무작위 추출법은 오랫동안 좋은 지름길이었고, 디지털 시대 이전에는 대규모 데이터 분석을 가능하게 해 주었다.", "order": ["그러나 추출을 하면 정보가 사라지는 반면, 전체에 가까운 데이터를 가지면 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 훨씬 커진다.", "이에 알맞은 예가 라이트 필드 카메라로, 한 평면이 아니라 전체 광선을 담아 두기 때문에 사진사는 무엇에 초점을 맞출지 나중에 정하면 된다.", "결과적으로 이 카메라의 정보는 전체 데이터에 더 가까워서, 촬영 전에 초점을 정해야 하는 일반 사진보다 더 재사용하기 쉽다."], "clue": ["'그러나'로 앞의 장점을 뒤집어 추출의 한계와 전체 데이터의 장점을 말함", "'이에 알맞은 예'가 앞의 전체 데이터의 자유로움을 예로 보여 줌", "'결과적으로'로 앞의 내용을 받아 일반 사진과 비교하며 마무리함"], "why": ["무작위 추출은 과거에 좋은 지름길", "추출은 정보를 잃고 전체 데이터는 더 자유로움", "라이트 필드 카메라가 좋은 예", "그래서 정보가 더 재사용 가능함"], "cards": ["결과적으로 이 카메라의 정보는 전체 데이터에 더 가까워서, 촬영 전에 초점을 정해야 하는 일반 사진보다 더 재사용하기 쉽다.", "이에 알맞은 예가 라이트 필드 카메라로, 한 평면이 아니라 전체 광선을 담아 두기 때문에 사진사는 무엇에 초점을 맞출지 나중에 정하면 된다.", "그러나 추출을 하면 정보가 사라지는 반면, 전체에 가까운 데이터를 가지면 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 훨씬 커진다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "For a long time, random sampling was a good shortcut.", "ko": "오랫동안, 무작위 추출법은 좋은 지름길이었다."}, {"n": 2, "en": "It made analysis of large data problems possible in the pre\u2011digital era.", "ko": "그것은 디지털 시대 이전에 상당한 데이터 문제 분석을 가능하게 했다."}, {"n": 3, "en": "But much as converting a digital image or song into a smaller file results in loss of data, information is lost when sampling.", "ko": "그러나 디지털 이미지나 노래를 더 작은 파일로 변환하는 것이 데이터 손실을 유발하는 것과 마찬가지로, 추출을 할 때 정보가 손실된다."}, {"n": 4, "en": "Having the full (or close to the full) dataset provides a lot more freedom to explore, to look at the data from different angles or to look closer at certain aspects of it.", "ko": "전체(또는 전체에 가까운) 데이터 세트를 가지는 것은 탐색하거나 다른 각도에서 데이터를 살펴보거나 그것의 특정 측면들을 더 자세히 보게 하는 자유를 훨씬 더 많이 제공한다."}, {"n": 5, "en": "A fitting example may be the light\u2011field camera, which captures not just a single plane of light, as with conventional cameras, but rays from the entire light field, some 11 million of them.", "ko": "라이트 필드 카메라가 적절한 비유가 될 수 있는데, 그것은 기존 카메라처럼 한 평면의 빛만 포착할 뿐만 아니라 약 1,100만 개에 달하는 전체 라이트 필드로부터의 광선들도 포착한다."}, {"n": 6, "en": "The photographers can decide later which element of an image to focus on in the digital file.", "ko": "사진사들은 디지털 파일에서 이미지의 어느 요소에 초점을 맞출지를 나중에 결정할 수 있다."}, {"n": 7, "en": "There is no need to focus at the beginning, since collecting all the information makes it possible to do that afterwards.", "ko": "모든 정보를 수집하는 것은 그것을 나중에 하는 것을 가능하게 만들기 때문에, 처음에 초점을 맞출 필요는 없다."}, {"n": 8, "en": "Because rays from the entire light field are included, it is closer to all the data.", "ko": "전체 라이트 필드의 빛이 포함되기 때문에, 그것은 모든 데이터에 더 가깝다."}, {"n": 9, "en": "As a result, the information is more \u201creuseable\u201d than ordinary pictures, where the photographer has to decide what to focus on before she presses the shutter.", "ko": "결과적으로 사진사가 셔터를 누르기 전에 그녀가 무엇에 초점을 맞출지를 결정해야 하는 일반 사진들보다 그 정보는 더 \u2018재사용 가능\u2019하다."}]}, {"id": "2311-38", "short": "23년 11월 38번", "group": "23년 11월", "num": 38, "topic_ko": "외향적 리더가 낫다는 고정 관념과 내향적 리더의 서번트 리더십", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 4, "summary_ko": "내향적 리더는 외향적 리더가 낫다는 억측을 극복해야 하며 이 고정 관념은 재검토해야 함"}, {"n": 2, "label": "뒷받침 1", "from": 5, "to": 5, "summary_ko": "남을 돕고 성장시키려는 열망은 리더십의 핵심이며 내향적인 사람에게 더 흔함"}, {"n": 3, "label": "뒷받침 2", "from": 6, "to": 7, "summary_ko": "서번트 리더십은 타인의 목표 달성을 도우며 겸손이 결국 보답받음"}], "gloss": [{"w": "introverted", "m": "내향적인", "form": "Introverted", "note": "형용사 introverted가 문장 첫머리라 대문자로 시작함"}, {"w": "extrovert", "m": "외향적인 사람", "form": "extroverts", "note": "명사 extrovert의 복수형(2번 문장에는 형용사 extroverted도 쓰임)"}, {"w": "presumption", "m": "억측, 추정"}, {"w": "executive", "m": "임원", "form": "executives", "note": "명사 executive의 복수형"}, {"w": "barrier", "m": "장애물"}, {"w": "stereotype", "m": "고정 관념"}, {"w": "reexamine", "m": "재검토하다"}, {"w": "empower", "m": "힘을 주다, 권한을 주다"}, {"w": "retain", "m": "유지하다", "form": "retaining", "note": "동사 retain의 동명사형(전치사 in 뒤)"}, {"w": "so-called", "m": "소위, 이른바", "form": "So\u2011called", "note": "형용사 so-called가 문장 첫머리라 대문자로 시작함"}, {"w": "adhere to", "m": "~을 고수하다", "form": "adheres", "note": "동사 adhere의 3인칭 단수 현재형(주어 leadership이 단수)"}, {"w": "humility", "m": "겸손"}, {"w": "pay off", "m": "결실을 맺다", "form": "pays off", "note": "동사 pay의 3인칭 단수 현재형(주어 humility가 단수)"}, {"w": "servant", "m": "하인, 남을 위해 봉사하는 사람"}], "qa": [{"chunk": 1, "q": "내향적인 리더가 극복해야 하는 것은?", "opts": ["리더는 겸손해서는 안 된다는 믿음", "외향적인 사람이 더 유능한 리더라는 강한 문화적 억측", "내향성은 타고나서 바꿀 수 없다는 믿음"], "ans": 1, "why": ["1번 문장이 근거이다.", "strong cultural presumption(강한 문화적 억측)을 극복해야 한다고 한다.", "\u201c리더는 겸손해서는 안 된다는 믿음\u201d은 극복 대상으로 나오지 않는다. 겸손은 7번 문장에서 오히려 결국 결실을 맺는다고 한다.", "\u201c내향성은 타고나서 바꿀 수 없다는 믿음\u201d도 지문에 없는 내용이다."], "ev_en": "Introverted leaders do have to overcome the strong cultural presumption that extroverts are more effective leaders.", "ev_ko": "내향적인 리더들은 외향적인 사람들이 더 유능한 리더라는 강력한 문화적 억측을 극복해야 한다."}, {"chunk": 2, "q": "Regent 대학교 연구에서 발견한 내용으로 알맞은 것은?", "opts": ["남을 돕고 성장시키려는 열망은 리더십과 관련이 없다.", "그런 열망은 리더가 되고 리더십을 유지하는 핵심 요소이며 내향적인 사람 사이에서 더 흔하다.", "그런 열망은 내향적인 사람보다 외향적인 사람 사이에서 더 흔하다."], "ans": 1, "why": ["5번 문장이 근거이다.", "열망이 a key factor(핵심 요소)이고 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라고 한다.", "\u201c리더십과 관련이 없다\u201d는 진술은 핵심 요소라는 말과 반대이다.", "\u201c외향적인 사람 사이에서 더 흔하다\u201d는 진술은 비교 대상이 거꾸로이다."], "ev_en": "Regent University found that a desire to be of service to others and to empower them to grow, which is more common among introverts than extroverts, is a key factor in becoming a leader and retaining leadership.", "ev_ko": "Regent 대학교는 다른 사람들에게 도움이 되고 그들이 성장할 수 있도록 힘을 주고자 하는 열망이 리더가 되고 리더십을 유지하는 데 핵심적인 요소이고, 그것이 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라는 것을 발견했다."}, {"chunk": 3, "q": "서번트 리더십의 설명으로 알맞은 것은?", "opts": ["리더가 관심을 끌어 구성원을 이끄는 것을 중요하게 여긴다.", "근로자나 고객이 목표를 달성하도록 도와 회사의 목표를 이룬다고 믿는다.", "회사의 목표를 먼저 이루고 나서 근로자를 돕는다."], "ans": 1, "why": ["6번 문장이 근거이다.", "회사의 목표는 근로자나 고객이 그들의 목표를 달성하도록 도울 때 가장 잘 달성된다고 믿는다.", "\u201c관심을 끌어 구성원을 이끈다\u201d는 진술은 7번 문장에서 이런 리더는 관심을 추구하지 않는다고 하므로 틀리다.", "\u201c회사의 목표를 먼저 이루고 나서 근로자를 돕는다\u201d는 진술은 순서가 거꾸로이다. 근로자를 도움으로써 회사의 목표가 이루어진다."], "ev_en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ev_ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}], "tf": [{"s": "관리자와 임원의 96% 이상이 외향적이다.", "t": true, "why": ["2번 문장이 근거이다.", "more than 96 percent of managers and executives are extroverted(관리자와 임원의 96% 이상이 외향적이다)라고 한다.", "인구는 거의 반반인데도 이렇게 쏠려 있다는 점이 핵심이다."], "ev_en": "Although the population splits into almost equal parts between introverts and extroverts, more than 96 percent of managers and executives are extroverted.", "ev_ko": "비록 인구는 내향적인 사람과 외향적인 사람 사이에서 거의 동등한 비율로 나뉘지만, 관리자와 임원의 96% 이상이 외향적이다."}, {"s": "필자는 외향적인 리더가 낫다는 고정 관념이 언제나 들어맞는다고 본다.", "t": false, "why": ["4번 문장은 이 고정 관념이 늘 들어맞지는 않는다(it doesn\u2019t always hold true)고 말한다.", "그래서 고정 관념을 다시 따져 봐야 한다(We must reexamine this stereotype)고 한다.", "올바른 내용은 고정 관념을 재검토해야 한다는 것이다."], "ev_en": "We must reexamine this stereotype, however, as it doesn\u2019t always hold true.", "ev_ko": "하지만 그것이 항상 맞는 것은 아니기 때문에 우리는 이 고정 관념을 재검토해야 한다."}, {"s": "2006년의 한 연구에서 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 보았다.", "t": true, "why": ["3번 문장이 근거이다.", "2006년 연구에서 기업 고위 임원의 65%가 내향성을 리더십의 장애물(a barrier to leadership)로 보았다."], "ev_en": "In a study done in 2006, 65 percent of senior corporate executives viewed introversion as a barrier to leadership.", "ev_ko": "2006년에 실시된 한 연구에서, 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 간주했다."}, {"s": "서번트 리더는 자신의 성과를 돋보이게 해 관심을 얻으려 한다.", "t": false, "why": ["7번 문장은 이런 리더가 관심을 추구하지 않는다(do not seek attention)고 한다.", "오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 한다(shine a light on others\u2019 wins and achievements)고 한다.", "올바른 내용은 자신이 아니라 남을 돋보이게 하려 한다는 것이다."], "ev_en": "Such leaders do not seek attention but rather want to shine a light on others\u2019 wins and achievements; servant leadership requires humility, but that humility ultimately pays off.", "ev_ko": "그런 리더들은 관심을 추구하는 것이 아니라 오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 하고, 서번트 리더십은 겸손을 필요로 하지만, 그 겸손은 궁극적으로 결실을 맺는다."}, {"s": "서번트 리더십은 고대 철학 문헌으로 거슬러 올라간다.", "t": true, "why": ["6번 문장이 근거이다.", "dating back to ancient philosophical literature(고대 철학 문헌으로 거슬러 올라가는)는 서번트 리더십을 꾸미는 말이다."], "ev_en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ev_ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}], "flow": {"fixed": "내향적인 리더는 외향적인 사람이 더 유능한 리더라는 강한 문화적 억측을 넘어서야 하며, 실제로 관리자와 임원의 96% 이상이 외향적이다.", "order": ["이를 뒷받침하는 수치로, 2006년의 한 연구에서 기업 고위 임원 상당수가 내향성을 리더십의 장애물로 보았지만, 이런 고정 관념은 늘 들어맞지는 않으므로 다시 따져 봐야 한다.", "고정 관념을 다시 따져 봐야 하는 근거로, 먼저 한 대학 연구는 남을 돕고 성장시키려는 열망이 리더가 되고 리더십을 유지하는 핵심이며 외향적인 사람보다 내향적인 사람에게 더 흔하다고 밝혔다.", "이어서 소개되는 이른바 서번트 리더십은, 근로자나 고객의 목표 달성을 도우면 회사의 목표도 가장 잘 이루어진다고 믿으며, 이 리더는 관심을 구하지 않고 겸손하게 남을 빛내어 결국 보답받는다."], "clue": ["'이를 뒷받침하는 수치'가 맨 위 덩어리의 96% 수치에 이어지고, '하지만'식 반전으로 재검토를 제기함", "'고정 관념을 다시 따져 봐야 하는 근거로'는 재검토 주장이 먼저 나온 뒤에만 올 수 있고, '먼저'가 이 연구 소개를 다음 덩어리보다 앞에 놓음", "앞 덩어리의 열망 제시가 끝난 뒤 '이어서'로 새 개념인 서번트 리더십을 소개함"], "why": ["내향적 리더는 억측을 넘어야 함", "관련 수치와 함께 고정 관념은 재검토해야 함", "재검토의 근거로 내향적인 사람에게 흔한 열망을 제시함", "이 열망과 통하는 서번트 리더십을 소개하며 겸손이 결국 보답받음을 말함"], "cards": ["이어서 소개되는 이른바 서번트 리더십은, 근로자나 고객의 목표 달성을 도우면 회사의 목표도 가장 잘 이루어진다고 믿으며, 이 리더는 관심을 구하지 않고 겸손하게 남을 빛내어 결국 보답받는다.", "고정 관념을 다시 따져 봐야 하는 근거로, 먼저 한 대학 연구는 남을 돕고 성장시키려는 열망이 리더가 되고 리더십을 유지하는 핵심이며 외향적인 사람보다 내향적인 사람에게 더 흔하다고 밝혔다.", "이를 뒷받침하는 수치로, 2006년의 한 연구에서 기업 고위 임원 상당수가 내향성을 리더십의 장애물로 보았지만, 이런 고정 관념은 늘 들어맞지는 않으므로 다시 따져 봐야 한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Introverted leaders do have to overcome the strong cultural presumption that extroverts are more effective leaders.", "ko": "내향적인 리더들은 외향적인 사람들이 더 유능한 리더라는 강력한 문화적 억측을 극복해야 한다."}, {"n": 2, "en": "Although the population splits into almost equal parts between introverts and extroverts, more than 96 percent of managers and executives are extroverted.", "ko": "비록 인구는 내향적인 사람과 외향적인 사람 사이에서 거의 동등한 비율로 나뉘지만, 관리자와 임원의 96% 이상이 외향적이다."}, {"n": 3, "en": "In a study done in 2006, 65 percent of senior corporate executives viewed introversion as a barrier to leadership.", "ko": "2006년에 실시된 한 연구에서, 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 간주했다."}, {"n": 4, "en": "We must reexamine this stereotype, however, as it doesn\u2019t always hold true.", "ko": "하지만 그것이 항상 맞는 것은 아니기 때문에 우리는 이 고정 관념을 재검토해야 한다."}, {"n": 5, "en": "Regent University found that a desire to be of service to others and to empower them to grow, which is more common among introverts than extroverts, is a key factor in becoming a leader and retaining leadership.", "ko": "Regent 대학교는 다른 사람들에게 도움이 되고 그들이 성장할 수 있도록 힘을 주고자 하는 열망이 리더가 되고 리더십을 유지하는 데 핵심적인 요소이고, 그것이 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라는 것을 발견했다."}, {"n": 6, "en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}, {"n": 7, "en": "Such leaders do not seek attention but rather want to shine a light on others\u2019 wins and achievements; servant leadership requires humility, but that humility ultimately pays off.", "ko": "그런 리더들은 관심을 추구하는 것이 아니라 오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 하고, 서번트 리더십은 겸손을 필요로 하지만, 그 겸손은 궁극적으로 결실을 맺는다."}]}, {"id": "2410-29", "short": "24년 10월 29번", "group": "24년 10월", "num": 29, "topic_ko": "조건부 장소 선호도로 동물이 원하는 것을 알아내는 방법", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "조건부 장소 선호도는 동물이 무엇을 원하는지 알아내는 방법이며, 두 장소를 서로 다른 경험과 연관시키도록 훈련시킴"}, {"n": 2, "label": "과정", "from": 3, "to": 6, "summary_ko": "두 장소를 명백히 다르게 만들고 경험 전후의 선호도를 측정해, 선택의 변화로 좋아했는지 싫어했는지 해석함"}, {"n": 3, "label": "예시", "from": 7, "to": 8, "summary_ko": "암에 걸린 쥐만 모르핀이 주어진 장소를 선호해, 그 쥐가 모르핀을 원했음을 보여 줌"}], "gloss": [{"w": "preference", "m": "선호(도)"}, {"w": "associate", "m": "연관시키다"}, {"w": "measure", "m": "측정하다", "form": "measured", "note": "동사 measure의 과거분사형(수동태 is measured)"}, {"w": "shift", "m": "변화, 이동"}, {"w": "reward", "m": "보상"}, {"w": "conversely", "m": "반대로"}, {"w": "avoid", "m": "피하다", "form": "avoids", "note": "동사 avoid의 3인칭 단수형(주어 it이 단수)"}, {"w": "stimulus", "m": "자극"}, {"w": "unpleasant", "m": "불쾌한"}, {"w": "relieve", "m": "완화하다, 덜어 주다"}, {"w": "saline", "m": "식염수"}, {"w": "mouse", "m": "쥐", "form": "mice", "note": "명사 mouse의 복수형(불규칙)"}], "qa": [{"chunk": 1, "q": "조건부 장소 선호도는 어떤 방법인가?", "opts": ["동물의 병을 치료하는 방법", "동물이 새 장소에 적응하게 하는 방법", "동물이 무엇을 원하는지 알아내는 방법"], "ans": 2, "why": ["첫 문장이 정의 그 자체임.", "조건부 장소 선호도(Conditioned Place Preference)는 동물이 무엇을 원하는지 알아내는 방법임.", "치료나 적응은 지문에 나오지 않음."], "ev_en": "Conditioned Place Preference is a way of finding out what animals want.", "ev_ko": "조건부 장소 선호도는 동물들이 무엇을 원하는지 알아내는 하나의 방법이다."}, {"chunk": 2, "q": "두 장소를 명백히 다르게 만드는 이유는?", "opts": ["동물이 두 장소 모두 싫어하게 하려고", "동물이 두 장소에서 오래 머물지 못하게 하려고", "동물이 두 장소를 경험과 쉽게 연관시키게 하려고"], "ans": 2, "why": ["두 장소를 다르게 하는 목적은 동물이 장소와 거기서 일어난 일을 쉽게 연관시키도록 하기 위함임.", "'두 장소를 모두 싫어하게 한다'거나 '오래 머물지 못하게 한다'는 내용은 지문에 없고, 장소와 경험을 쉽게 연관시키려는 것이 목적임."], "ev_en": "The two places are made obviously different to make it as easy as possible for the animal to associate each place with what happened to it there.", "ev_ko": "그 두 장소는 그 동물이 각 장소를 거기에서 그것에게 일어난 일과 연관시키는 것을 가능한 한 쉽게 만들기 위해 명백히 다르게 만들어진다."}, {"chunk": 3, "q": "암에 걸린 쥐가 모르핀이 주어진 장소를 선호한 것은 무엇을 시사하는가?", "opts": ["그 쥐가 식염수를 싫어했다는 것", "그 쥐가 모르핀을 원했다는 것", "건강한 쥐도 모르핀을 원했다는 것"], "ans": 1, "why": ["마지막 문장에서 암에 걸린 쥐가 모르핀을 원했음을 시사한다고 결론 내림.", "건강한 쥐는 그런 선호가 생기지 않았으므로 '건강한 쥐도 모르핀을 원했다'는 내용은 틀림.", "식염수를 싫어했다는 내용은 없음. 선호의 대상은 모르핀이 주어진 장소임."], "ev_en": "This suggests that the mice with cancer wanted the morphine.", "ev_ko": "이것은 암에 걸린 쥐가 그 모르핀을 원했음을 시사한다."}], "tf": [{"s": "동물의 선호도는 두 장소에서의 경험이 끝난 뒤에만 측정된다.", "t": false, "why": ["틀린 부분은 \"뒤에만\"임.", "선호도는 경험 전과 후에 모두 측정됨."], "ev_en": "The animal\u2019s preference for being in one place or another is measured both before and after its experiences in the two places.", "ev_ko": "한 장소나 다른 장소에 있는 것에 대한 그 동물의 선호도는 두 장소에서 경험하기 전과 후에 모두 측정된다."}, {"s": "연구자는 한 장소는 어떤 경험과, 다른 장소는 대개 아무 일도 일어나지 않는 것과 연관시키도록 동물을 훈련시킨다.", "t": true, "why": ["한 장소는 음식이나 시끄러운 소리 같은 경험, 다른 장소는 대개 아무 일도 없음으로 훈련하므로 맞음."], "ev_en": "Researchers train them to associate one place with an experience such as food or a loud noise and another place with something completely different, usually where nothing happens.", "ev_ko": "연구자들은 그것들이 한 장소를 음식이나 시끄러운 소리와 같은 경험과 연관시키고 또 다른 장소를 완벽히 다른 어떤 것과 연관시키도록 훈련시키는데 대개 그곳에서는 아무것도 일어나지 않는다."}, {"s": "동물이 자극이 나타났던 장소를 피하기 시작하면, 그 자극을 불쾌하게 느꼈음을 시사한다.", "t": true, "why": ["자극이 있던 장소를 피하고 반대쪽을 선호하면 불쾌했다는 뜻이므로 맞음."], "ev_en": "Conversely, if it now avoids the place the stimulus appeared and starts to prefer the place it did not experience it, then this suggests that it found the stimulus unpleasant.", "ev_ko": "반대로, 만약 그것이 이제 자극이 나타났던 장소를 피하고 그것이 그것을 경험하지 않았던 장소를 선호하기 시작한다면, 그러면 이것은 그것이 그 자극을 불쾌하게 느꼈다는 것을 시사한다."}, {"s": "동물이 보상을 위해 시간을 보내는 장소를 바꾸면, 그 경험을 좋아해서 반복하려는 것으로 해석할 수 있다.", "t": true, "why": ["선택하는 장소에 변화가 있으면 동물이 그 경험을 좋아했고 반복하려 한다는 뜻이므로 맞음."], "ev_en": "If there is a shift in where the animal chooses to spend its time for the reward, this suggests that it liked the experience and is trying to repeat it.", "ev_ko": "만약 동물이 보상을 위해 어디에서 시간을 보내기로 선택하는지에 변화가 있다면, 이것은 그것이 그 경험을 좋아했고 그것을 반복하려고 노력하는 중이라는 것을 시사한다."}, {"s": "건강한 쥐도 암에 걸린 쥐처럼 모르핀이 주어진 장소를 선호하게 되었다.", "t": false, "why": ["틀린 부분은 건강한 쥐도 선호했다는 점임.", "건강한 쥐는 그러한 선호가 생기지 않았음."], "ev_en": "For example, mice with cancer show a preference for the place where they have been given morphine, a drug used to relieve pain, rather than where they have received saline whereas healthy mice developed no such preference.", "ev_ko": "예를 들어, 암에 걸린 쥐가 식염수를 받아 왔었던 곳보다 통증을 완화시키는 데 사용되는 약인 모르핀이 주어졌었던 장소에 대한 선호를 보여 준 반면, 건강한 쥐는 그러한 선호가 생기지 않았다."}], "flow": {"fixed": "조건부 장소 선호도는 동물이 무엇을 원하는지 알아내는 하나의 방법이다.", "order": ["이를 위해 구체적으로 연구자는 동물이 한 장소는 음식이나 시끄러운 소리 같은 경험과, 다른 장소는 아무 일도 없는 상태와 연관시키도록 훈련시키며, 두 장소는 확연히 다르게 만든다.", "그 뒤 경험 전후의 선호도를 비교해, 경험이 있던 장소를 더 택하면 그 경험을 좋아한 것이고 그곳을 피하면 불쾌하게 여긴 것으로 해석한다.", "예를 들어 암에 걸린 쥐는 진통제인 모르핀이 주어진 장소를 선호했지만 건강한 쥐는 그러지 않아, 암에 걸린 쥐가 모르핀을 원했음을 알 수 있다."], "clue": ["\"이를 위해 구체적으로\"로 앞 문장의 목적(원하는 것 알아내기)을 받아 방법(훈련)을 설명함", "\"그 뒤\"로 훈련 다음 단계인 선호도 비교\u00b7해석을 이어 감", "\"예를 들어\"로 마지막에 구체적 사례를 제시함"], "why": ["정의 -> 훈련 방법 -> 결과 해석 -> 쥐 실험 예시 순서임."], "cards": ["이를 위해 구체적으로 연구자는 동물이 한 장소는 음식이나 시끄러운 소리 같은 경험과, 다른 장소는 아무 일도 없는 상태와 연관시키도록 훈련시키며, 두 장소는 확연히 다르게 만든다.", "예를 들어 암에 걸린 쥐는 진통제인 모르핀이 주어진 장소를 선호했지만 건강한 쥐는 그러지 않아, 암에 걸린 쥐가 모르핀을 원했음을 알 수 있다.", "그 뒤 경험 전후의 선호도를 비교해, 경험이 있던 장소를 더 택하면 그 경험을 좋아한 것이고 그곳을 피하면 불쾌하게 여긴 것으로 해석한다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "Conditioned Place Preference is a way of finding out what animals want.", "ko": "조건부 장소 선호도는 동물들이 무엇을 원하는지 알아내는 하나의 방법이다."}, {"n": 2, "en": "Researchers train them to associate one place with an experience such as food or a loud noise and another place with something completely different, usually where nothing happens.", "ko": "연구자들은 그것들이 한 장소를 음식이나 시끄러운 소리와 같은 경험과 연관시키고 또 다른 장소를 완벽히 다른 어떤 것과 연관시키도록 훈련시키는데 대개 그곳에서는 아무것도 일어나지 않는다."}, {"n": 3, "en": "The two places are made obviously different to make it as easy as possible for the animal to associate each place with what happened to it there.", "ko": "그 두 장소는 그 동물이 각 장소를 거기에서 그것에게 일어난 일과 연관시키는 것을 가능한 한 쉽게 만들기 위해 명백히 다르게 만들어진다."}, {"n": 4, "en": "The animal\u2019s preference for being in one place or another is measured both before and after its experiences in the two places.", "ko": "한 장소나 다른 장소에 있는 것에 대한 그 동물의 선호도는 두 장소에서 경험하기 전과 후에 모두 측정된다."}, {"n": 5, "en": "If there is a shift in where the animal chooses to spend its time for the reward, this suggests that it liked the experience and is trying to repeat it.", "ko": "만약 동물이 보상을 위해 어디에서 시간을 보내기로 선택하는지에 변화가 있다면, 이것은 그것이 그 경험을 좋아했고 그것을 반복하려고 노력하는 중이라는 것을 시사한다."}, {"n": 6, "en": "Conversely, if it now avoids the place the stimulus appeared and starts to prefer the place it did not experience it, then this suggests that it found the stimulus unpleasant.", "ko": "반대로, 만약 그것이 이제 자극이 나타났던 장소를 피하고 그것이 그것을 경험하지 않았던 장소를 선호하기 시작한다면, 그러면 이것은 그것이 그 자극을 불쾌하게 느꼈다는 것을 시사한다."}, {"n": 7, "en": "For example, mice with cancer show a preference for the place where they have been given morphine, a drug used to relieve pain, rather than where they have received saline whereas healthy mice developed no such preference.", "ko": "예를 들어, 암에 걸린 쥐가 식염수를 받아 왔었던 곳보다 통증을 완화시키는 데 사용되는 약인 모르핀이 주어졌었던 장소에 대한 선호를 보여 준 반면, 건강한 쥐는 그러한 선호가 생기지 않았다."}, {"n": 8, "en": "This suggests that the mice with cancer wanted the morphine.", "ko": "이것은 암에 걸린 쥐가 그 모르핀을 원했음을 시사한다."}]}, {"id": "2410-30", "short": "24년 10월 30번", "group": "24년 10월", "num": 30, "topic_ko": "새들의 번식기 결정 요인과 그 예외", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "적도 근처 새는 일 년 내내 번식하지만, 온대\u00b7극지방 새는 낮의 길이 변화로 번식기가 뚜렷이 정해짐"}, {"n": 2, "label": "전개", "from": 4, "to": 6, "summary_ko": "먹이가 최고조일 때 새끼를 기르며, 다른 때에는 번식 기관이 줄어 번식이 불가능함"}, {"n": 3, "label": "예외와 다양성", "from": 7, "to": 13, "summary_ko": "유목성 사막 종은 비가 오면 번식을 시작하며, 종마다 번식기를 나누는 방식이 다름"}], "gloss": [{"w": "breed", "m": "번식하다"}, {"w": "temperate", "m": "온화한, 온대의"}, {"w": "trigger", "m": "촉발하다", "form": "triggered", "note": "동사 trigger의 과거분사형(수동태 are triggered)"}, {"w": "reluctant", "m": "꺼리는"}, {"w": "incapable", "m": "~할 수 없는"}, {"w": "reproductive", "m": "번식의, 생식의"}, {"w": "shrink", "m": "줄어들다", "form": "shrinks", "note": "동사 shrink의 3인칭 단수 현재형(주어 their reproductive system이 단수)"}, {"w": "exception", "m": "예외"}, {"w": "nomadic", "m": "유목하는"}, {"w": "initiate", "m": "시작하다"}, {"w": "brood", "m": "한배에서 태어난 새끼 무리 (본문의 broods는 복수형)"}, {"w": "exceptionally", "m": "유난히"}, {"w": "successive", "m": "잇따른"}, {"w": "songbird", "m": "명금(\u9cf4\u79bd), 노래하는 작은 새", "form": "songbirds", "note": "명사 songbird의 복수형"}], "qa": [{"chunk": 1, "q": "온대와 극지방에서 새의 번식기를 촉발하는 주된 요인은?", "opts": ["먹이 종류의 변화", "낮의 길이 변화", "기온의 급격한 상승"], "ans": 1, "why": ["3번 문장에서 번식기는 주로 낮의 길이 변화에 의해 촉발된다고 함.", "먹이나 기온은 이 문장의 요인이 아님."], "ev_en": "They are triggered mainly by changes in day length.", "ev_ko": "그것들은 주로 낮의 길이의 변화에 의해 촉발된다."}, {"chunk": 2, "q": "대부분의 새가 번식기가 아닌 때 번식하지 못하는 이유는?", "opts": ["먹이를 구할 수 없어서 죽기 때문", "번식 기관이 줄어들어 신체적으로 불가능하기 때문", "천적을 피해 이동하기 때문"], "ans": 1, "why": ["5번 문장: 새들은 다른 때에 번식을 꺼릴 뿐 아니라 신체적으로도 불가능함.", "6번 문장: 번식 기관이 줄어들며, 이는 나는 새가 몸무게를 줄이게 도움.", "죽음이나 천적은 지문에 없음."], "ev_en": "This is because their reproductive system shrinks, which helps flying birds save weight.", "ev_ko": "이것은 왜냐하면 그들의 번식 기관이 줄어들기 때문이고, 이 사실은 나는 새들이 몸무게를 줄일 수 있도록 도와준다."}, {"chunk": 3, "q": "유목성 사막 종이 비가 온 지 며칠 안에 번식 주기를 시작할 수 있는 이유는?", "opts": ["갑작스러운 번식 기회를 최대한 활용하기 위해", "낮의 길이 변화에 맞추기 위해", "번식 기관을 줄여 몸무게를 줄이기 위해"], "ans": 0, "why": ["8번 문장에서 비 온 뒤 며칠 안에 번식을 시작한다고 했고, 그 이유를 9번 문장이 밝힘: 갑작스러운 번식 기회를 최대한 활용하기 위함.", "낮의 길이와 번식 기관 축소는 일반 규칙이며, 사막 종은 그 규칙의 예외임."], "ev_en": "It\u2019s for making the most of the sudden breeding opportunity.", "ev_ko": "그것은 갑작스러운 번식 기회를 최대한으로 활용하기 위한 것이다."}], "tf": [{"s": "적도 근처에서는 많은 종의 새가 일 년 내내 번식한다.", "t": true, "why": ["적도 근처 새의 많은 종은 일 년 내내 번식하므로 맞음."], "ev_en": "Near the equator, many species of bird breed all year round.", "ev_ko": "적도 근처에서, 새의 많은 종들은 일 년 내내 번식한다."}, {"s": "유난히 좋은 해에도 참새 한 쌍은 한 무리의 새끼만 기를 수 있다.", "t": false, "why": ["틀린 부분은 \"한 무리만\"임.", "유난히 좋은 해에는 참새 한 쌍이 잇따라 여러 무리의 새끼를 기를 수 있음."], "ev_en": "In an exceptionally good year, a pair of House Sparrows, a kind of songbird, can raise successive broods through a marathon reproductive effort.", "ev_ko": "유난히 좋은 해에는 명금(\u9cf4\u79bd)의 한 종류인 참새 한 쌍은 마라톤과 같은 번식 노력을 통해 잇따라 태어난 여러 무리의 함께 태어난 새끼들을 기를 수 있다."}, {"s": "대부분의 새는 번식기가 아닌 때에도 신체적으로는 번식할 수 있지만 꺼릴 뿐이다.", "t": false, "why": ["틀린 부분은 \"신체적으로는 할 수 있다\"임.", "대부분의 새는 꺼릴 뿐 아니라 신체적으로도 번식할 수 없음."], "ev_en": "Most birds are not simply reluctant to breed at other times but they are also physically incapable of doing so.", "ev_ko": "대부분의 새들은 다른 때에 번식하기를 단지 꺼리는 것뿐만 아니라 또한 신체적으로 그렇게 할 수 없는 것이다."}, {"s": "대부분의 바닷새는 한 무리의 새끼를 기른다.", "t": true, "why": ["대부분의 바닷새는 한 배에서 난 새끼 무리(brood) 하나를 기르므로 맞음."], "ev_en": "Most seabirds raise a single brood.", "ev_ko": "대부분의 바닷새들은 한 무리의 함께 태어난 새끼를 기른다."}, {"s": "따뜻한 지역의 명금은 몇 달 안에 여러 무리의 새끼를 기를 수도 있다.", "t": true, "why": ["명금이 몇 달 안에 여러 가족(여러 무리의 새끼)을 기를 수도 있으므로 맞음."], "ev_en": "In warm regions, however, songbirds may raise several families in a few months.", "ev_ko": "그러나, 따뜻한 지역에서는, 명금(\u9cf4\u79bd)들이 몇 달 안에 여러 자녀들을 기를 수도 있다."}], "flow": {"fixed": "적도 근처에서는 많은 종의 새가 일 년 내내 번식하지만, 온대와 극지방에서는 번식기가 뚜렷이 정해져 있고 그 계기는 주로 낮의 길이 변화이다.", "order": ["그 결과 새들은 먹이 공급이 최고조일 때 새끼를 기르게 되며, 대부분의 새는 다른 때에는 번식 기관이 줄어들어 번식하고 싶어도 할 수 없다.", "그러나 유목성 사막 종은 이 규칙의 예외여서, 비가 내리면 며칠 안에 번식 주기를 시작해 갑작스러운 기회를 최대한 활용한다.", "또한 이런 예외 말고도 종마다 번식 기간을 나누는 방식이 달라서, 대부분의 바닷새는 한 무리만 기르지만 따뜻한 지역의 명금은 여러 무리를 기를 수도 있다."], "clue": ["\"그 결과\"로 앞의 번식기 결정(낮의 길이)의 결과를 설명함", "\"그러나 ... 예외\"로 앞의 일반 규칙에 반대되는 사례를 제시함", "\"또한 이런 예외 말고도\"가 앞의 예외 설명을 받아 종별 차이를 덧붙임"], "why": ["일반 규칙 -> 그 결과 -> 사막 종 예외 -> 종별 번식 방식 차이 순서임."], "cards": ["또한 이런 예외 말고도 종마다 번식 기간을 나누는 방식이 달라서, 대부분의 바닷새는 한 무리만 기르지만 따뜻한 지역의 명금은 여러 무리를 기를 수도 있다.", "그 결과 새들은 먹이 공급이 최고조일 때 새끼를 기르게 되며, 대부분의 새는 다른 때에는 번식 기관이 줄어들어 번식하고 싶어도 할 수 없다.", "그러나 유목성 사막 종은 이 규칙의 예외여서, 비가 내리면 며칠 안에 번식 주기를 시작해 갑작스러운 기회를 최대한 활용한다."], "answer": [1, 2, 0]}, "sents": [{"n": 1, "en": "Near the equator, many species of bird breed all year round.", "ko": "적도 근처에서, 새의 많은 종들은 일 년 내내 번식한다."}, {"n": 2, "en": "But in temperate and polar regions, the breeding seasons of birds are often sharply defined.", "ko": "하지만 온대와 극지방에서는 새들의 번식기들이 대개 뚜렷하게 정해진다."}, {"n": 3, "en": "They are triggered mainly by changes in day length.", "ko": "그것들은 주로 낮의 길이의 변화에 의해 촉발된다."}, {"n": 4, "en": "If all goes well, the outcome is that birds raise their young when the food supply is at its peak.", "ko": "만약에 모든 것이 잘 진행된다면, 결과는 새들이 먹이 공급이 최고조에 이를 때 새끼들을 기르는 것이다."}, {"n": 5, "en": "Most birds are not simply reluctant to breed at other times but they are also physically incapable of doing so.", "ko": "대부분의 새들은 다른 때에 번식하기를 단지 꺼리는 것뿐만 아니라 또한 신체적으로 그렇게 할 수 없는 것이다."}, {"n": 6, "en": "This is because their reproductive system shrinks, which helps flying birds save weight.", "ko": "이것은 왜냐하면 그들의 번식 기관이 줄어들기 때문이고, 이 사실은 나는 새들이 몸무게를 줄일 수 있도록 도와준다."}, {"n": 7, "en": "The main exception to this rule are nomadic desert species.", "ko": "유목성 사막 종은 이 규칙의 주요 예외이다."}, {"n": 8, "en": "These can initiate their breeding cycle within days of rain.", "ko": "이들은 비가 오는 날들에 번식 주기를 시작할 수 있다."}, {"n": 9, "en": "It\u2019s for making the most of the sudden breeding opportunity.", "ko": "그것은 갑작스러운 번식 기회를 최대한으로 활용하기 위한 것이다."}, {"n": 10, "en": "Also, different species divide the breeding season up in different ways.", "ko": "또한, 다른 종들은 번식 기간을 다른 방식으로 나눈다."}, {"n": 11, "en": "Most seabirds raise a single brood.", "ko": "대부분의 바닷새들은 한 무리의 함께 태어난 새끼를 기른다."}, {"n": 12, "en": "In warm regions, however, songbirds may raise several families in a few months.", "ko": "그러나, 따뜻한 지역에서는, 명금(\u9cf4\u79bd)들이 몇 달 안에 여러 자녀들을 기를 수도 있다."}, {"n": 13, "en": "In an exceptionally good year, a pair of House Sparrows, a kind of songbird, can raise successive broods through a marathon reproductive effort.", "ko": "유난히 좋은 해에는 명금(\u9cf4\u79bd)의 한 종류인 참새 한 쌍은 마라톤과 같은 번식 노력을 통해 잇따라 태어난 여러 무리의 함께 태어난 새끼들을 기를 수 있다."}]}, {"id": "2410-33", "short": "24년 10월 33번", "group": "24년 10월", "num": 33, "topic_ko": "읽기를 하나로 정의할 수 없고 폭넓은 스펙트럼으로 이해해야 함", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "읽기가 다른 행동과 깔끔히 분리되는 단일한 개념이라는 주장에 대해 정말 그렇게 단순한지 의문을 제기함"}, {"n": 2, "label": "전개", "from": 3, "to": 5, "summary_ko": "읽기는 공통된 하나의 특성 없는 느슨한 행동의 묶음이어서 읽기와 비읽기의 구분은 실패함"}, {"n": 3, "label": "마무리", "from": 6, "to": 7, "summary_ko": "예외적 읽기 형태를 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 함"}], "gloss": [{"w": "consistent", "m": "일관된"}, {"w": "concept", "m": "개념"}, {"w": "productive", "m": "생산적인"}, {"w": "resemblance", "m": "닮음, 유사성", "form": "resemblances", "note": "명사 resemblance의 복수형"}, {"w": "trait", "m": "특성"}, {"w": "distinguish", "m": "구별하다"}, {"w": "destined", "m": "~할 운명인"}, {"w": "qualify", "m": "자격이 있다, 자격을 얻다", "form": "qualifies", "note": "동사 qualify의 3인칭 단수 현재형 (주어 what이 단수로 취급됨)"}, {"w": "boundary", "m": "경계", "form": "boundaries", "note": "명사 boundary의 복수형(y를 i로 바꾸고 es)"}, {"w": "exceptional", "m": "예외적인"}, {"w": "expansive", "m": "광범위한"}, {"w": "accommodate", "m": "수용하다"}, {"w": "edge case", "m": "특이 사례, 경계 사례", "form": "edge cases", "note": "명사 edge case의 복수형"}, {"w": "forum", "m": "토론의 장, 공개 토론 마당"}], "qa": [{"chunk": 1, "q": "1~2번 문장에서 일부 사람들의 주장에 대한 필자의 태도는?", "opts": ["읽기가 그렇게 단순한지 의문을 제기한다", "주장이 옳다고 확신한다", "주장을 근거 없이 무시한다"], "ans": 0, "why": ["1번 문장은 일부 사람들의 주장을 소개함.", "2번 문장 \"읽기는 정말로 그렇게 단순할까?\"는 그 주장에 대한 의문 제기임."], "ev_en": "Is reading really that simple?", "ev_ko": "읽기는 정말로 그렇게 단순할까?"}, {"chunk": 2, "q": "읽기와 읽기가 아닌 것을 구분하려는 노력이 실패하는 이유는?", "opts": ["읽기를 가르치는 사람이 부족하기 때문", "책 이외의 읽기 자료가 너무 적기 때문", "무엇이 읽기인지에 대한 동의가 애초에 없기 때문"], "ans": 2, "why": ["4번 문장에서 이유를 직접 밝힘: 애초에 무엇이 읽기로서 자격이 있는지에 대한 합의가 없음.", "교사 수나 자료 양은 지문에 없음."], "ev_en": "Consequently, efforts to distinguish reading from nonreading are destined to fail because there is no agreement on what qualifies as reading in the first place.", "ev_ko": "결론적으로, 읽기와 읽기가 아닌 것을 구분하려는 노력은 실패로 돌아가는데, 왜냐하면 애초에 무엇이 읽기로서의 자격을 주는가에 대한 동의가 없기 때문이다."}, {"chunk": 3, "q": "필자가 예외적인 읽기 형태를 모으는 시도로 도달하려는 이해는?", "opts": ["하나의 명확한 기준으로 정리된 읽기", "책 읽기와 다른 행동의 엄격한 구분", "다양한 읽기 활동을 수용할 만큼 넓은 스펙트럼으로서의 읽기"], "ans": 2, "why": ["7번 문장: 그 시도는 별개의 읽기 활동들을 수용할 만큼 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전함.", "필자는 읽기를 하나의 명확한 기준으로 정리하거나 책 읽기와 다른 행동을 엄격히 구분하는 것에 반대하고, 폭넓은 스펙트럼으로 이해하려 함."], "ev_en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ev_ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}], "tf": [{"s": "필자는 읽기가 다른 행동과 분리되는 단일하고 일관된 개념이라는 주장에 동의한다.", "t": false, "why": ["틀린 부분은 \"동의한다\"임.", "단일하고 일관된 개념은 일부 사람들의 주장이고, 필자는 \"읽기는 정말 그렇게 단순할까?\"라고 의문을 제기함.", "필자는 읽기를 공통된 하나의 특성 없이 느슨하게 묶인 행동의 묶음으로 봄."], "ev_en": "The most productive way to think about reading is as a loosely related set of behaviors that belong together owing to family resemblances, as Ludwig Wittgenstein used the phrase, without having in common a single defining trait.", "ev_ko": "읽기에 대해 생각하는 가장 생산적인 방식은 하나의 명백한 특성을 공통적으로 가지지 않은 채 Ludwig Wittgenstein이 그 어구를 사용한 것처럼 가족 유사성 때문에 함께 속하게 되는 헐겁게 연결된 행동의 묶음으로서이다."}, {"s": "일부 사람들은 읽기가 책으로 하는 다른 행동들과 깔끔히 분리되는 하나의 개념이라고 주장한다.", "t": true, "why": ["읽기를 다른 행동과 깔끔히 분리되는 단일하고 일관된 개념으로 보는 것은 일부 사람들의 주장이므로 맞음."], "ev_en": "Some people argue that there is a single, logically consistent concept known as reading that can be neatly set apart from everything else people do with books.", "ev_ko": "몇몇 사람들은 사람들이 책을 가지고 하는 모든 다른 행동들로부터 깔끔하게 분리될 수 있는, 읽기로 알려진 유일하고 논리적으로 일관성 있는 개념이 있다고 주장한다."}, {"s": "필자는 예외적인 읽기 형태를 모으는 시도가 읽기를 폭넓은 스펙트럼으로 이해하는 쪽으로 이어진다고 본다.", "t": true, "why": ["그 시도는 별개의 읽기 활동들을 수용할 만큼 광범위한 스펙트럼으로 읽기를 이해하는 것으로 발전한다고 했으므로 맞음."], "ev_en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ev_ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}, {"s": "읽기의 경계를 알아내려 할수록 경계를 넓히는 특이 사례는 줄어든다.", "t": false, "why": ["틀린 부분은 \"줄어든다\"임.", "경계를 알려 할수록 특이 사례가 더 많이 발견됨."], "ev_en": "The more one tries to figure out where the border lies between reading and not\u2011reading, the more edge cases will be found to stretch the term\u2019s flexible boundaries.", "ev_ko": "읽기와 읽기가 아닌 것 사이의 경계가 어디에 있는가를 알려고 하면 할수록, 더욱 많은 특이 사례들이 그 용어의 유연한 경계를 확장하고 있다는 것이 밝혀질 것이다."}, {"s": "예외적인 읽기 형태들을 한데 모아 놓은 하나의 토론의 장(forum, 의견을 나누는 자리)은, 읽기의 경계를 정하려는 사람들이 겪는 어려움을 부각한다.", "t": true, "why": ["모아 놓은 하나의 토론의 장(forum, 의견을 나누는 마당)이 경계를 정하려는 누구나 겪는 어려움을 부각한다고 했으므로 맞음."], "ev_en": "Thus, it is worth attempting to collect together these exceptional forms of reading into a single forum, one highlighting the challenges faced by anyone wishing to establish the boundaries where reading begins and ends.", "ev_ko": "그러므로, 이러한 예외적인 읽기의 형태들을 모두 함께 하나의 토론의 장으로 모으려는 시도는 해 볼 가치가 있으며, 그 토론의 장은 어디서 읽기가 시작되고 끝나는가에 대한 경계를 정하기를 원하는 누구나에 의해 마주하게 될 어려움들을 돋보이게 한다."}], "flow": {"fixed": "일부 사람들은 읽기가 책으로 하는 다른 행동들과 깔끔히 구분되는 하나의 일관된 개념이라고 주장하지만, 읽기가 정말 그렇게 단순할까?", "order": ["그렇지 않다. 읽기는 하나의 공통된 특성 없이 가족 유사성 때문에 묶이는, 헐겁게 연결된 행동의 묶음으로 보는 것이 가장 생산적이다.", "따라서 읽기와 읽기가 아닌 것을 가르려는 노력은 무엇이 읽기인지에 대한 합의가 없어 실패하고, 경계를 찾을수록 특이 사례는 더 늘어난다.", "그러므로 이런 예외적인 읽기 형태들을 한데 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 해 준다."], "clue": ["'그렇지 않다'가 고정 덩어리의 의문(\"그렇게 단순할까?\")에 직접 답하며 새 관점을 제시함", "\"따라서\"로 앞의 관점의 귀결(구분 실패)을 이끎", "\"그러므로\"로 앞 내용을 바탕으로 한 최종 제안을 제시함"], "why": ["단순한 정의 주장 -> 느슨한 묶음이라는 관점 -> 구분 실패 -> 스펙트럼 이해 순서임."], "cards": ["그러므로 이런 예외적인 읽기 형태들을 한데 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 해 준다.", "따라서 읽기와 읽기가 아닌 것을 가르려는 노력은 무엇이 읽기인지에 대한 합의가 없어 실패하고, 경계를 찾을수록 특이 사례는 더 늘어난다.", "그렇지 않다. 읽기는 하나의 공통된 특성 없이 가족 유사성 때문에 묶이는, 헐겁게 연결된 행동의 묶음으로 보는 것이 가장 생산적이다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Some people argue that there is a single, logically consistent concept known as reading that can be neatly set apart from everything else people do with books.", "ko": "몇몇 사람들은 사람들이 책을 가지고 하는 모든 다른 행동들로부터 깔끔하게 분리될 수 있는, 읽기로 알려진 유일하고 논리적으로 일관성 있는 개념이 있다고 주장한다."}, {"n": 2, "en": "Is reading really that simple?", "ko": "읽기는 정말로 그렇게 단순할까?"}, {"n": 3, "en": "The most productive way to think about reading is as a loosely related set of behaviors that belong together owing to family resemblances, as Ludwig Wittgenstein used the phrase, without having in common a single defining trait.", "ko": "읽기에 대해 생각하는 가장 생산적인 방식은 하나의 명백한 특성을 공통적으로 가지지 않은 채 Ludwig Wittgenstein이 그 어구를 사용한 것처럼 가족 유사성 때문에 함께 속하게 되는 헐겁게 연결된 행동의 묶음으로서이다."}, {"n": 4, "en": "Consequently, efforts to distinguish reading from nonreading are destined to fail because there is no agreement on what qualifies as reading in the first place.", "ko": "결론적으로, 읽기와 읽기가 아닌 것을 구분하려는 노력은 실패로 돌아가는데, 왜냐하면 애초에 무엇이 읽기로서의 자격을 주는가에 대한 동의가 없기 때문이다."}, {"n": 5, "en": "The more one tries to figure out where the border lies between reading and not\u2011reading, the more edge cases will be found to stretch the term\u2019s flexible boundaries.", "ko": "읽기와 읽기가 아닌 것 사이의 경계가 어디에 있는가를 알려고 하면 할수록, 더욱 많은 특이 사례들이 그 용어의 유연한 경계를 확장하고 있다는 것이 밝혀질 것이다."}, {"n": 6, "en": "Thus, it is worth attempting to collect together these exceptional forms of reading into a single forum, one highlighting the challenges faced by anyone wishing to establish the boundaries where reading begins and ends.", "ko": "그러므로, 이러한 예외적인 읽기의 형태들을 모두 함께 하나의 토론의 장으로 모으려는 시도는 해 볼 가치가 있으며, 그 토론의 장은 어디서 읽기가 시작되고 끝나는가에 대한 경계를 정하기를 원하는 누구나에 의해 마주하게 될 어려움들을 돋보이게 한다."}, {"n": 7, "en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}]}];
